B.aJ4=s(["\u064a\u0627 \u0644\u064e\u0634\u0631\u0641\u0650 \u0627\u0644\u0635\u062d\u0628\u0629 \u0648\u064a\u0627 \u0644\u0650\u0639\u0644\u0648\u0651\u0650 \u0627\u0644\u0645\u0646\u0632\u0644\u0629\u060c \u062d\u064a\u0646 \u0646\u0627\u0644 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0634\u0631\u0641\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0631 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0625\u0630 \u062e\u064f\u0635\u0651\u064e \u0645\u0646 \u0628\u064a\u0646 \u0627\u0644\u062e\u0644\u0642 \u0628\u0643\u0644\u0645\u0629: \u0644\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0647\u0650\u061b \u062a\u0644\u0643 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u064f\u0642\u0627\u0644\u064f \u0625\u0644\u0627 \u0644\u0645\u0646 \u0639\u0644\u0627 \u0642\u062f\u0631\u064f\u0647 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0628\u0644\u063a \u0645\u0646 \u0627\u0644\u0635\u062d\u0628\u0629 \u0645\u0646\u0632\u0644\u0629\u064b \u0641\u0627\u0642\u062a \u0627\u0644\u062b\u0631\u064a\u0627.","\u0648\u0647\u0643\u0630\u0627\u060c \u062a\u062c\u0644\u0651\u064e\u062a \u0639\u0646\u0627\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0623\u0648\u0644\u064a\u0627\u0626\u0650\u0647\u0650 \u0627\u0644\u0635\u0627\u062f\u0642\u064a\u0646\u060c \u0641\u062b\u0628\u0651\u064e\u062a\u064e \u0642\u0644\u0648\u0628\u064e\u0647\u0645\u060c \u0648\u064a\u0633\u0651\u064e\u0631\u064e \u0644\u0647\u0645 \u0633\u064f\u0628\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u062c\u0627\u0629\u060c \u0648\u062c\u0639\u0644 \u0641\u064a \u0637\u064a\u0651\u0650 \u0627\u0644\u0645\u0650\u062d\u0646\u0629\u0650 \u0628\u064f\u0634\u0631\u0649 \u0627\u0644\u0646\u0651\u064e\u0635\u0631."],t.s)
