B.aSg=s(["\u0643\u0627\u0646 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u062a\u0627\u062c\u0631\u064b\u0627 \u0630\u0627 \u0645\u0627\u0644\u060c \u0644\u0627 \u064a\u0639\u062a\u0645\u062f \u0641\u064a \u0645\u0639\u064a\u0634\u062a\u0647 \u0639\u0644\u0649 \u0643\u0648\u0646\u0647 \u0648\u0632\u064a\u0631\u064b\u0627 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0644\u0627 \u064a\u062c\u0639\u0644 \u0645\u0646 \u0645\u0643\u0627\u0646\u062a\u0647 \u0648\u0633\u064a\u0644\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0645\u0635\u0644\u062d\u0629\u060c \u0628\u0644 \u0639\u0627\u0634 \u0639\u0641\u064a\u0641\u064b\u0627 \u0643\u0631\u064a\u0645 \u0627\u0644\u0646\u0641\u0633\u060c \u064a\u0631\u0649 \u0627\u0644\u0645\u0627\u0644 \u0623\u0645\u0627\u0646\u0629 \u0641\u064a \u0639\u0646\u0642\u0647\u060c \u0648\u0625\u0630\u0627 \u062f\u0639\u0627\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0646\u0641\u0642\u0629\u060c \u0628\u0627\u062f\u0631 \u0628\u0645\u0627 \u0641\u064a \u064a\u062f\u0647\u060c \u0644\u0627 \u064a\u064f\u0639\u0631\u0641 \u0644\u0644\u062a\u0644\u0643\u0624\u060c \u0648\u0644\u0627 \u0644\u0644\u062a\u0631\u062f\u0651\u062f \u0625\u0644\u0649 \u0642\u0644\u0628\u0647 \u0633\u0628\u064a\u0644\u0627\u064b.","\u0644\u0645\u0627 \u0639\u0632\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0644\u0649 \u0627\u0644\u062e\u0631\u0648\u062c \u0625\u0644\u0649 \u062a\u0628\u0648\u0643\u060c \u0641\u064a \u0648\u0642\u062a\u064d \u0627\u0634\u062a\u062f\u0651 \u0641\u064a\u0647 \u0627\u0644\u0643\u0631\u0628\u060c \u0648\u0642\u0644\u0651 \u0641\u064a\u0647 \u0627\u0644\u0645\u0627\u0644\u060c \u0648\u062a\u0628\u0627\u064a\u0646\u062a \u0641\u064a\u0647 \u0627\u0644\u0639\u0632\u0627\u0626\u0645\u060c \u062c\u0627\u0621 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u064a\u062d\u0645\u0644 \u0645\u0627\u0644\u0647 \u0643\u0644\u0651\u0647\u060c \u0641\u0648\u0636\u0639\u0647 \u0628\u064a\u0646 \u064a\u062f\u064a \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0641\u0642\u0627\u0644 \u0644\u0647: \u0645\u0627 \u0623\u0628\u0642\u064a\u062a\u064e \u0644\u0623\u0647\u0644\u0643\u061f \u0642\u0627\u0644: \u0623\u0628\u0642\u064a\u062a\u064f \u0644\u0647\u0645 \u0627\u0644\u0644\u0647\u064e \u0648\u0631\u0633\u0648\u0644\u064e\u0647 - \u0631\u0648\u0627\u0647 \u0627\u0644\u062a\u0631\u0645\u0630\u064a.","\u062d\u062a\u0649 \u0642\u0627\u0644 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0645\u0627 \u0633\u0628\u0642\u062a\u064f \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0625\u0644\u0649 \u062e\u064a\u0631\u064d \u0642\u0637\u0651 \u0625\u0644\u0627 \u0633\u0628\u0642\u0646\u064a \u0625\u0644\u064a\u0647.","\u0641\u0647\u0630\u0627 \u0627\u0644\u0641\u0639\u0644 \u064a\u0635\u062f\u0631 \u0645\u0646 \u0642\u0644\u0628\u064d \u0635\u0627\u062f\u0642\u060c \u0648\u0646\u064a\u0651\u0629\u064d \u062e\u0627\u0644\u0635\u0629\u060c \u0648\u062a\u0648\u0643\u0651\u064f\u0644\u064d \u062d\u0642\u0651\u064d\u060c \u0644\u0639\u0645\u0644\u064d \u0644\u0627 \u0631\u062c\u0639\u0629 \u0641\u064a\u0647\u060c \u0648\u0645\u064e\u0646 \u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0633\u0628\u0642 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d\u060c \u0648\u0642\u062f \u0648\u0647\u0628 \u0644\u0644\u0647 \u0643\u0644\u0651 \u0645\u0627 \u064a\u0645\u0644\u0643\u060c \u0648\u0644\u0645 \u064a\u0644\u062a\u0641\u062a."],t.s)
