B.aTk=s(["\u0643\u0627\u0646\u062a \u062e\u0637\u0628\u0629 \u0623\u0628\u064a \u0628\u0643\u0631 \u0645\u064a\u062b\u0627\u0642\u064b\u0627 \u062c\u0627\u0645\u0639\u064b\u0627 \u0644\u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0644\u0645\u0627 \u0633\u0645\u0639 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0643\u0644\u0645\u0627\u062a\u0650\u0647\u060c \u0623\u062f\u0631\u0643\u0648\u0627 \u0623\u0646\u0647\u0645 \u0623\u0645\u0627\u0645 \u0631\u062c\u0644\u064d \u0644\u0627 \u064a\u0637\u0644\u0628 \u0645\u0644\u0643\u064b\u0627\u060c \u0628\u0644 \u0639\u0628\u062f\u064b\u0627 \u0644\u0644\u0647\u060c \u062d\u0645\u0644 \u0623\u0645\u0627\u0646\u0629\u064b \u062b\u0642\u064a\u0644\u0629 \u0639\u0644\u0649 \u0639\u0627\u062a\u0642\u0647\u060c \u064a\u0633\u062a\u0645\u062f \u0645\u0646\u0647\u062c\u064e\u0647 \u0645\u0646 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0633\u0646\u0629 \u0646\u0628\u064a\u0651\u0647 \ufdfa.","\u0628\u062f\u0623\u0647\u0627 \u0628\u0625\u0642\u0631\u0627\u0631\u064d \u062a\u0648\u0627\u0636\u0639\u0647\u060c \u0646\u0627\u0641\u064a\u064b\u0627 \u0639\u0646 \u0646\u0641\u0633\u0647 \u0627\u0644\u062a\u0641\u0636\u064a\u0644\u060c \u0644\u064a\u0624\u0643\u0651\u062f \u0623\u0646 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u062a\u0643\u0644\u064a\u0641 \u0644\u0627 \u062a\u0634\u0631\u064a\u0641\u060c \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0641\u064a\u0647\u0627 \u0641\u0648\u0642 \u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629\u060c \u0648\u062c\u0639\u0644 \u0637\u0627\u0639\u062a\u0647 \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0627\u0644\u0634\u0631\u0639\u064a\u0629 \u0644\u0627 \u062a\u064f\u0633\u062a\u0645\u062f \u0645\u0646 \u0627\u0644\u0645\u0646\u0635\u0628\u060c \u0628\u0644 \u0645\u0646 \u0645\u062f\u0649 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0634\u0631\u0639.","\u0648\u0641\u064a \u062b\u0646\u0627\u064a\u0627 \u0643\u0644\u0645\u0627\u062a\u0647\u060c \u0628\u064a\u0651\u0646 \u0623\u0646 \u0627\u0644\u0639\u062f\u0644 \u0647\u0648 \u0631\u0643\u064a\u0632\u0629 \u0627\u0644\u062d\u0643\u0645\u060c \u0648\u0623\u0646 \u0631\u0641\u0639 \u0627\u0644\u0638\u0644\u0645 \u0639\u0646 \u0627\u0644\u0636\u0639\u064a\u0641\u060c \u0648\u0623\u062e\u0630 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0642\u0648\u064a\u060c \u0641\u0631\u064a\u0636\u0629 \u0644\u0627 \u062e\u064a\u0627\u0631 \u0641\u064a\u0647\u0627\u060c \u0648\u0623\u0646 \u062a\u0631\u0643 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u0641\u0633\u0627\u062f \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0633\u0628\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0644 \u0648\u0627\u0644\u0628\u0644\u0627\u0621.","\u0648\u0628\u0647\u0630\u0627\u060c \u062a\u0644\u062e\u0651\u0635\u062a \u0641\u064a \u062e\u0637\u0628\u062a\u0647 \u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0634\u0631\u0639\u064a\u0629: \u062d\u0627\u0643\u0645 \u0645\u0624\u062a\u0645\u0650\u0646 \u0639\u0644\u0649 \u0627\u0644\u062f\u064a\u0646\u060c \u0644\u0627 \u062a\u064f\u062c\u0628 \u0637\u0627\u0639\u062a\u0647 \u0625\u0644\u0627 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u064a\u064f\u062d\u0627\u0633\u064e\u0628 \u0648\u0644\u0627 \u064a\u064f\u0642\u062f\u0651\u064e\u0633\u060c \u0648\u064a\u062c\u0639\u0644 \u0645\u0646 \u0627\u0644\u0642\u064a\u0645 \u0648\u0627\u0644\u0645\u0628\u0627\u062f\u0626 \u0631\u0643\u064a\u0632\u0629\u064b \u0641\u064a \u0628\u0646\u0627\u0621 \u0627\u0644\u0623\u0645\u0629 \u0648\u062b\u0628\u0627\u062a\u0647\u0627."],t.s)
