B.aRE=s(["\u0643\u0627\u0646 \u0623\u0648\u0644 \u0645\u0627 \u0623\u0642\u0631\u0651\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u0639\u062f \u0648\u0641\u0627\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0625\u0646\u0641\u0627\u0630 \u0623\u0645\u0631\u0650 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u062a\u062c\u0647\u064a\u0632 \u062c\u064a\u0634\u0650 \u0623\u0633\u0627\u0645\u0629 \u0628\u0646 \u0632\u064a\u062f\u060c \u0627\u0644\u0630\u064a \u0648\u0644\u0627\u0651\u0647 \u0627\u0644\u0642\u064a\u0627\u062f\u0629\u060c \u0648\u0623\u0645\u0631\u0647 \u0628\u0627\u0644\u062a\u0648\u062c\u0647 \u0625\u0644\u0649 \u0645\u0634\u0627\u0631\u0641 \u0627\u0644\u0634\u0627\u0645.","\u0648\u0631\u063a\u0645 \u062d\u062f\u0627\u062b\u0629 \u0633\u0646\u0651\u0647\u060c \u0625\u0630 \u0644\u0645 \u064a\u0628\u0644\u063a \u0627\u0644\u062b\u0627\u0645\u0646\u0629 \u0639\u0634\u0631\u0629\u060c \u0641\u0642\u062f \u0623\u0645\u0636\u0649 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0627\u0644\u0623\u0645\u0631 \u062f\u0648\u0646 \u062a\u0631\u062f\u0651\u062f\u060c \u0644\u064a\u0624\u0643\u062f \u0623\u0646 \u0645\u0627 \u0628\u062f\u0623\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0627 \u0628\u062f \u0623\u0646 \u064a\u064f\u0633\u062a\u0643\u0645\u0644\u060c \u0648\u0623\u0646 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0644\u0627 \u062a\u064f\u0628\u0646\u0649 \u0639\u0644\u0649 \u062a\u0642\u0627\u062f\u0645 \u0627\u0644\u0639\u0645\u0631\u060c \u0641\u0636\u0644\u064b\u0627 \u0639\u0646 \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0647\u0648 \u0645\u0646 \u0627\u062e\u062a\u0627\u0631\u0647 \u0644\u0647\u0630\u0627 \u0627\u0644\u0645\u0642\u0627\u0645.","\u0648\u0642\u062f \u062a\u0631\u062f\u0651\u062f \u0628\u0639\u0636\u064f \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u0644\u0627 \u062a\u064f\u0631\u0633\u0644 \u0627\u0644\u062c\u064a\u0634\u060c \u0648\u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0628\u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0645\u0646 \u064a\u062d\u0645\u064a\u0647\u0627! \u0644\u0643\u0646 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u062c\u0627\u0628\u0647\u0645 \u0628\u0643\u0644\u0645\u0629\u064d \u062d\u0627\u0632\u0645\u0629: \u0648\u0627\u0644\u0644\u0647\u060c \u0644\u0627 \u0623\u064f\u062d\u0644\u0651 \u0639\u064f\u0642\u062f\u0629\u064b \u0639\u0642\u062f\u0647\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0644\u0648 \u0623\u0646 \u0627\u0644\u0637\u064a\u0631\u064e \u062a\u064e\u062e\u0637\u0641\u064e\u0646\u0627\u060c \u0648\u0627\u0644\u0633\u0628\u0627\u0639\u064e \u0645\u0646 \u062d\u0648\u0644 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0644\u0648 \u0623\u0646 \u0627\u0644\u0643\u0644\u0627\u0628 \u062c\u064e\u0631\u0651\u064e\u062a \u0628\u0623\u0631\u062c\u0644 \u0623\u0645\u0647\u0627\u062a \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0644\u0623\u064f\u062c\u0647\u0632\u0646\u0651\u064e \u0628\u0639\u062b\u064e \u0623\u0633\u0627\u0645\u0629.","\u0641\u0643\u0627\u0646 \u0630\u0644\u0643 \u062f\u0631\u0633\u064b\u0627 \u0641\u064a \u0627\u0644\u0639\u0642\u064a\u062f\u0629 \u0648\u0635\u062f\u0642\u0650 \u0627\u0644\u0627\u062a\u0651\u0650\u0628\u0627\u0639 \u0644\u0644\u0646\u0628\u064a\u060c \u0648\u0623\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0644\u0627 \u062a\u0645\u0648\u062a \u0628\u0645\u0648\u062a \u0635\u0627\u062d\u0628\u0647\u0627\u060c \u0648\u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0625\u0646 \u063a\u0627\u0628 \u062c\u0633\u062f\u0647\u060c \u0641\u0648\u0635\u0627\u064a\u0627\u0647 \u0628\u0627\u0642\u064a\u0629\u060c \u0644\u0627 \u062a\u064f\u0631\u0627\u062c\u064e\u0639\u060c \u0648\u0644\u0627 \u064a\u064f\u062a\u0623\u062e\u0651\u0631 \u0639\u0646 \u062a\u0646\u0641\u064a\u0630\u0647\u0627."],t.s)
