B.aG8=s([u.af,"\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u064a\u064e\u0623\u0645\u064f\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0645\u064e\u0646 \u0627\u0633\u062a\u064a\u0642\u064e\u0638 \u0645\u0650\u0646 \u0645\u064e\u0646\u0627\u0645\u0650\u0647 \u0648\u0623\u0631\u0627\u062f\u064e \u0627\u0644\u0648\u0636\u0648\u0621\u064e\u060c \u0641\u0644\u064a\u064e\u0633\u062a\u0646\u062b\u0650\u0631 \u062b\u0644\u0627\u062b\u064e \u0645\u0631\u0651\u064e\u0627\u062a\u064d\u060c \u0648\u0627\u0644\u0627\u0633\u062a\u0646\u062b\u0627\u0631\u064f \u0647\u0648 \u0627\u0633\u062a\u0646\u0634\u0627\u0642\u064f \u0627\u0644\u0645\u0627\u0621\u0650 \u0628\u0627\u0644\u0623\u0646\u0641\u0650\u060c \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u062b\u0631\u064f\u0647 \u0648\u0646\u0641\u062e\u064f\u0647 \u0648\u0625\u062e\u0631\u0627\u062c\u064f\u0647\u060c \xab\u0641\u0625\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u064e \u064a\u064e\u0628\u0650\u064a\u062a\u064f \u0639\u0644\u0649 \u062e\u064e\u064a\u0634\u0648\u0645\u0650\u0647\xbb\u060c \u0648\u0627\u0644\u062e\u064a\u0634\u0648\u0645\u064f: \u0647\u0648 \u0627\u0644\u0623\u0646\u0641\u064f\u060c \u0648\u0642\u064a\u0644: \u0623\u0642\u0635\u064e\u0649 \u0627\u0644\u0623\u0646\u0641\u0650.","\u0648\u0627\u0644\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u0649 \u0648\u0631\u0633\u0648\u0644\u064f\u0647 \u0623\u0639\u0644\u064e\u0645\u064f \u0628\u062d\u064e\u0642\u064a\u0642\u0629\u0650 \u0647\u0630\u0647 \u0627\u0644\u0645\u064e\u0628\u064a\u062a\u0650\u060c \u0648\u0646\u062d\u0646 \u0646\u064f\u0624\u0645\u0650\u0646\u064f \u0628\u0645\u0627 \u0642\u0627\u0644\u0647 \u0631\u064e\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u062c\u0627\u0632\u0645\u064b\u0627\u060c \u0648\u0646\u064e\u0645\u062a\u062b\u0650\u0644\u064f \u0645\u0627 \u0623\u0645\u064e\u0631\u064e\u0646\u0627 \u0628\u0647\u060c \u0645\u0639 \u062a\u064e\u0633\u0644\u064a\u0645\u0650\u0646\u0627 \u0623\u0646\u0651\u064e\u0647 \ufdfa \u0642\u062f \u062e\u064e\u0635\u0651\u064e\u0647 \u0627\u0644\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u064e\u0649 \u0628\u0623\u0645\u0648\u0631\u064d \u062a\u064e\u0642\u0635\u064f\u0631\u064f \u0639\u0646 \u0641\u064e\u0647\u0645\u0650\u0647\u0627 \u0648\u0625\u062f\u0631\u0627\u0643\u0650\u0647\u0627 \u0639\u064f\u0642\u0648\u0644\u064f \u0639\u0627\u0645\u0651\u064e\u0629\u0650 \u0627\u0644\u0628\u064e\u0634\u0631\u0650.","\u0648\u0642\u064a\u0644: \u0638\u0627\u0647\u0631\u064f \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u064a\u064e\u0642\u062a\u0636\u064a \u0623\u0646 \u064a\u064e\u062d\u0635\u064f\u0644\u064e \u0647\u0630\u0627 \u0644\u0643\u0644\u0651\u0650 \u0646\u0627\u0626\u0645\u064d\u060c \u0648\u064a\u064e\u062d\u062a\u0645\u0650\u0644\u064f \u0623\u0646 \u064a\u0643\u0648\u0646\u064e \u0645\u064e\u062e\u0635\u0648\u0635\u064b\u0627 \u0628\u0645\u064e\u0646 \u0644\u0645 \u064a\u064e\u062d\u062a\u0631\u0650\u0632 \u0645\u0650\u0646 \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u0650 \u0628\u0634\u064e\u064a\u0621\u064d \u0645\u0650\u0646 \u0627\u0644\u0630\u0651\u0650\u0643\u0631\u0650."],t.s)
