B.ayd=s(["\u0647\u064a\u0645\u0646\u062a \u0627\u0644\u062a\u0642\u0627\u0644\u064a\u062f\u064f \u0648\u0627\u0644\u0623\u0639\u0631\u0627\u0641\u064f \u0639\u0644\u0649 \u062d\u064a\u0627\u0629 \u0627\u0644\u0639\u0631\u0628\u060c \u0648\u0623\u0635\u0628\u062d\u062a \u0644\u0647\u0645 \u0642\u0648\u0627\u0646\u064a\u0646 \u0639\u0631\u0641\u064a\u0629 \u062a\u062d\u0643\u0645 \u0627\u0644\u0623\u062d\u0633\u0627\u0628\u064e \u0648\u0627\u0644\u0623\u0646\u0633\u0627\u0628 \u0648\u0639\u0644\u0627\u0642\u0627\u062a\u0650 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0628\u0639\u0636\u0647\u0627 \u0628\u0628\u0639\u0636 \u0648\u0627\u0644\u0623\u0641\u0631\u0627\u062f \u0643\u0630\u0644\u0643\u060c \u0648\u064a\u0645\u0643\u0646 \u0625\u062c\u0645\u0627\u0644 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0641\u064a\u0645\u0627 \u064a\u0623\u062a\u064a:","\u0627\u0644\u0627\u0639\u062a\u0632\u0627\u0632 \u0628\u0627\u0644\u0623\u0646\u0633\u0627\u0628 \u0648\u0627\u0644\u0623\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062a\u0641\u0627\u062e\u0631 \u0628\u0647\u0645\u0627: \u0641\u0642\u062f \u062d\u064e\u0631\u064e\u0635\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0639\u0644\u0649 \u0623\u0646\u0633\u0627\u0628\u0647\u0645 \u0641\u0644\u0645 \u064a\u064f\u0635\u0627\u0647\u0650\u0631\u0648\u0627 \u063a\u064a\u0631\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u062c\u0646\u0627\u0633 \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0621 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0642\u0636\u0649 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0648\u0628\u064a\u064e\u0651\u0646 \u0623\u0646 \u0627\u0644\u062a\u0641\u0627\u0636\u0644 \u0625\u0646\u0645\u0627 \u0647\u0648 \u0628\u0627\u0644\u062a\u0642\u0648\u0649 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d.","\u0627\u0644\u0627\u0639\u062a\u0632\u0627\u0632 \u0628\u0627\u0644\u0643\u0644\u0645\u0629 \u0648\u0633\u0644\u0637\u0627\u0646\u0647\u0627 \u0648\u0644\u0627 \u0633\u064a\u0645\u0627 \u0627\u0644\u0634\u0639\u0631: \u0641\u0642\u062f \u0643\u0627\u0646\u062a \u062a\u0633\u062a\u0647\u0648\u064a\u0647\u0645 \u0627\u0644\u0643\u0644\u0645\u0629\u064f \u0627\u0644\u0641\u0635\u064a\u062d\u0629 \u0648\u0627\u0644\u0623\u0633\u0644\u0648\u0628\u064f \u0627\u0644\u0628\u0644\u064a\u063a\u060c \u0648\u0643\u0627\u0646 \u0634\u0639\u0631\u0647\u0645 \u0633\u0650\u062c\u0644\u064e\u0651 \u0645\u0641\u0627\u062e\u0631\u0647\u0645 \u0648\u0623\u062d\u0633\u0627\u0628\u0647\u0645 \u0648\u0623\u0646\u0633\u0627\u0628\u0647\u0645 \u0648\u062f\u064a\u0648\u0627\u0646\u064e \u0645\u0639\u0627\u0631\u0641\u0647\u0645 \u0648\u0639\u0648\u0627\u0637\u0641\u0647\u0645\u060c \u0641\u0644\u0627 \u062a\u0639\u062c\u0628 \u0625\u0630\u0627 \u0646\u062c\u0645 \u0641\u064a\u0647\u0645 \u0627\u0644\u062e\u0637\u0628\u0627\u0621\u064f \u0627\u0644\u0645\u0635\u0627\u0642\u0639 \u0648\u0627\u0644\u0634\u0639\u0631\u0627\u0621\u064f \u0627\u0644\u0641\u064f\u0637\u0627\u062d\u0644\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0628\u064a\u062a\u064f \u0645\u0646 \u0627\u0644\u0634\u0639\u0631 \u064a\u064e\u0631\u0641\u0639 \u0627\u0644\u0642\u0628\u064a\u0644\u0629 \u0648\u0627\u0644\u0628\u064a\u062a\u064f \u064a\u064e\u062e\u0641\u0636\u0647\u0627\u060c \u0648\u0644\u0630\u0644\u0643 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0641\u0631\u062d\u0648\u0646 \u0628\u0634\u064a\u0621 \u0641\u0631\u062d\u064e\u0647\u0645 \u0628\u0634\u0627\u0639\u0631 \u064a\u064e\u0646\u0628\u064f\u063a \u0641\u064a \u0627\u0644\u0642\u0628\u064a\u0644\u0629.","\u0648\u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u0639\u0631\u0628\u064f \u0623\u0647\u0644\u064e \u0643\u062a\u0627\u0628\u064d \u0648\u0639\u0644\u0645\u064d \u0643\u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0628\u0644 \u0643\u0627\u0646 \u064a\u064e\u063a\u0644\u0628 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u062c\u0647\u0644\u064f \u0648\u0627\u0644\u0623\u064f\u0645\u0650\u0651\u064a\u064e\u0651\u0629\u060c \u0648\u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064f \u0648\u0627\u0644\u062c\u0645\u0648\u062f\u064f \u0639\u0644\u0649 \u0627\u0644\u0642\u062f\u064a\u0645 -\u0648\u0625\u0646 \u0643\u0627\u0646 \u0628\u0627\u0637\u0644\u0627\u064b- \u0648\u0643\u0627\u0646\u062a \u0623\u0645\u0629\u064f \u0627\u0644\u0639\u0631\u0628 \u0644\u0627 \u062a\u064e\u0643\u062a\u0628 \u0648\u0644\u0627 \u062a\u064e\u062d\u0633\u064f\u0628 \u0648\u0647\u0630\u0647 \u0647\u064a \u0627\u0644\u0635\u0641\u0629\u064f \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u063a\u0627\u0644\u0628\u0629\u064b \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0643\u0627\u0646 \u0641\u064a\u0647\u0645 \u0642\u0644\u064a\u0644\u064c \u0645\u0645\u0646 \u064a\u064e\u0643\u062a\u0628 \u0648\u064a\u064e\u0642\u0631\u0623 \u0648\u0645\u0639 \u0623\u064f\u0645\u0650\u0651\u064a\u064e\u0651\u062a\u0647\u0645 \u0648\u0639\u062f\u0645 \u0627\u062a\u0633\u0627\u0639 \u0645\u0639\u0627\u0631\u0641\u0647\u0645 \u0641\u0642\u062f \u0643\u0627\u0646\u0648\u0627 \u064a\u064e\u0634\u062a\u0647\u0631\u0648\u0646 \u0628\u0627\u0644\u0630\u0643\u0627\u0621\u060c \u0648\u0627\u0644\u0641\u0637\u0646\u0629\u060c \u0648\u0627\u0644\u0623\u064e\u0644\u0645\u064e\u0639\u0650\u064a\u064e\u0651\u0629\u060c \u0648\u0644\u064f\u0637\u0641 \u0627\u0644\u0645\u0634\u0627\u0639\u0631\u060c \u0648\u0625\u0650\u0631\u0647\u0627\u0641 \u0627\u0644\u062d\u0650\u0633\u0651\u060c \u0648\u062d\u064f\u0633\u0646 \u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0647\u064e\u064a\u064f\u0651\u0624 \u0644\u0642\u0628\u0648\u0644 \u0627\u0644\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0639\u0631\u0641\u0629\u060c \u0648\u0627\u0644\u062a\u0648\u062c\u064a\u0647\u0650 \u0627\u0644\u0631\u0634\u064a\u062f\u061b \u0648\u0644\u0630\u0644\u0643 \u0644\u0645\u0627 \u062c\u0627\u0621 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064f \u0635\u0627\u0631\u0648\u0627 \u0639\u064f\u0644\u064e\u0645\u0627\u0621\u060c \u062d\u064f\u0643\u064e\u0645\u0627\u0621\u060c \u0641\u064f\u0642\u064e\u0647\u0627\u0621\u060c \u0648\u0632\u0627\u0644\u062a \u0639\u0646\u0647\u0645 \u0627\u0644\u0623\u064f\u0645\u0650\u0651\u064a\u064e\u0651\u0629\u060c \u0648\u0623\u0635\u0628\u062d \u0627\u0644\u0639\u0644\u0645\u064f \u0648\u0627\u0644\u0645\u0639\u0631\u0641\u0629\u064f \u0645\u0646 \u0623\u062e\u0635\u0650\u0651 \u062e\u0635\u0627\u0626\u0635\u0647\u0645\u060c \u0648\u0643\u0627\u0646 \u0641\u064a\u0647\u0645 \u0645\u0646 \u0645\u064e\u0647\u064e\u0631\u064e \u0641\u064a \u0639\u0650\u0644\u0645 \u0642\u064e\u0635\u0650\u0651 \u0627\u0644\u0623\u062b\u0631\u060c \u0648\u0647\u0648 \u0627\u0644\u0642\u0650\u064a\u0627\u0641\u0629\u060c \u0648\u0643\u0627\u0646 \u0641\u064a\u0647\u0645 \u0623\u0637\u0628\u0627\u0621\u064f \u0643\u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0643\u0644\u062f\u0629\u060c \u0648\u0643\u0627\u0646 \u0637\u0650\u0628\u064f\u0651\u0647\u0645 \u0645\u064e\u0628\u0646\u064a\u064b\u0651\u0627 \u0639\u0644\u0649 \u0627\u0644\u062a\u062c\u0627\u0631\u0628 \u0627\u0644\u062a\u064a \u0627\u0643\u062a\u0633\u0628\u0648\u0647\u0627 \u0645\u0646 \u0627\u0644\u062d\u064a\u0627\u0629 \u0648\u0627\u0644\u0628\u064a\u0626\u0629."],t.s)
