B.aCm=s(["\u0643\u0627\u0646\u062a \u0642\u0644\u0648\u0628\u064f\u0647\u0645 \u0635\u0627\u0641\u064a\u0629\u064b \u0644\u0645 \u062a\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0641\u0644\u0633\u0641\u0627\u062a\u064f \u0648\u0627\u0644\u0623\u0633\u0627\u0637\u064a\u0631\u064f \u0648\u0627\u0644\u062e\u0631\u0627\u0641\u0627\u062a\u064f \u0627\u0644\u062a\u064a \u064a\u0635\u0639\u0628 \u0625\u0632\u0627\u0644\u062a\u0647\u0627\u060c \u0643\u0645\u0627 \u0641\u064a \u0627\u0644\u0634\u0639\u0648\u0628 \u0627\u0644\u0647\u0646\u062f\u064a\u0629 \u0648\u0627\u0644\u0631\u0648\u0645\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0641\u0627\u0631\u0633\u064a\u0629\u060c \u0641\u0643\u0623\u0646\u0645\u0627 \u0643\u0627\u0646\u062a \u062a\u064f\u0639\u064e\u062f\u064f\u0651 \u0644\u062d\u0645\u0644 \u0623\u0639\u0638\u0645 \u0631\u0633\u0627\u0644\u0629 \u0641\u064a \u0627\u0644\u0648\u062c\u0648\u062f\u060c \u0648\u0647\u064a \u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u062e\u0627\u0644\u062f\u0629\u060c \u0648\u0644\u0647\u0630\u0627 \u0643\u0627\u0646\u0648\u0627 \u0623\u062d\u0641\u0638\u064e \u0634\u0639\u0628\u064d \u0639\u064f\u0631\u0650\u0641 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0632\u0645\u0646\u060c \u0641\u0648\u062c\u064e\u0651\u0647 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064f \u0642\u0631\u064a\u062d\u0629\u064e \u0627\u0644\u062d\u0641\u0638 \u0648\u0627\u0644\u0630\u0643\u0627\u0621 \u0625\u0644\u0649 \u062d\u0641\u0638 \u0627\u0644\u062f\u064a\u0646 \u0648\u062d\u0645\u0627\u064a\u062a\u0647\u060c \u0641\u0643\u0627\u0646\u062a \u0642\u0648\u0627\u0647\u0645 \u0627\u0644\u0641\u0643\u0631\u064a\u0629\u064f \u0648\u0645\u0648\u0627\u0647\u0628\u064f\u0647\u0645 \u0627\u0644\u0641\u0637\u0631\u064a\u0629 \u0645\u064e\u0630\u062e\u0648\u0631\u0629\u064b \u0641\u064a\u0647\u0645 \u0644\u0645 \u062a\u064f\u0633\u062a\u064e\u0647\u0644\u064e\u0643 \u0641\u064a \u0641\u0644\u0633\u0641\u0627\u062a \u062e\u064a\u0627\u0644\u064a\u0629\u060c \u0648\u0644\u0627 \u0641\u064a \u062c\u062f\u0644\u064d \u0628\u064a\u0632\u0646\u0637\u064a\u064d\u0651 \u0639\u0642\u064a\u0645\u060c \u0648\u0644\u0627 \u0641\u064a \u0645\u0630\u0627\u0647\u0628\u064e \u0643\u0644\u0627\u0645\u064a\u0629\u064d \u0645\u0639\u0642\u062f\u0629.","\u0648\u0627\u062a\u0633\u0627\u0639\u064f \u0644\u063a\u062a\u0650\u0647\u0645 \u062f\u0644\u064a\u0644\u064c \u0639\u0644\u0649 \u0642\u0648\u0629 \u062d\u0641\u0638\u0650\u0647\u0645 \u0648\u0630\u0627\u0643\u0631\u062a\u0650\u0647\u0645\u060c \u0641\u0625\u0630\u0627 \u0643\u0627\u0646 \u0644\u0644\u0639\u0633\u0644 \u062b\u0645\u0627\u0646\u0648\u0646 \u0627\u0633\u0645\u064b\u0627 \u0648\u0644\u0644\u062b\u0639\u0644\u0628 \u0645\u0626\u062a\u0627\u0646 \u0648\u0644\u0644\u0623\u0633\u062f \u062e\u0645\u0633\u0645\u0627\u0626\u0629\u060c \u0648\u0644\u0644\u062c\u0645\u0644 \u0623\u0644\u0641\u064b\u0627\u060c \u0648\u0643\u0630\u0627 \u0627\u0644\u0633\u064a\u0641\u060c \u0648\u0644\u0644\u062f\u0627\u0647\u064a\u0629 \u0646\u062d\u0648 \u0623\u0631\u0628\u0639\u0629 \u0622\u0644\u0627\u0641 \u0627\u0633\u0645\u060c \u0648\u0644\u0627 \u0634\u0643 \u0623\u0646 \u0627\u0633\u062a\u064a\u0639\u0627\u0628 \u0647\u0630\u0647 \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0630\u0627\u0643\u0631\u0629 \u0642\u0648\u064a\u0629 \u062d\u0627\u0636\u0631\u0629 \u0648\u0642\u064e\u0651\u0627\u062f\u0629\u060c \u0648\u0642\u062f \u0628\u0644\u064e\u063a \u0628\u0647\u0645 \u0627\u0644\u0630\u0643\u0627\u0621\u064f \u0648\u0627\u0644\u0641\u0637\u0646\u0629\u064f \u0625\u0644\u0649 \u0627\u0644\u0641\u0647\u0645 \u0628\u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0641\u0636\u0644\u0627\u064b \u0639\u0646 \u0627\u0644\u0639\u0628\u0627\u0631\u0629\u060c \u0648\u0627\u0644\u0623\u0645\u062b\u0644\u0629 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0643\u062b\u064a\u0631\u0629."],t.s)
