B.aSK=s(["\u0623\u0648\u0644\u0627\u064b: \u0627\u0644\u062a\u0645\u064a\u064a\u0632\u064f \u0627\u0644\u0648\u0627\u0636\u062d \u0628\u064a\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u062d\u062f\u064a\u062b\u061b \u0625\u0630 \u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u064a\u0623\u0645\u0631 \u0628\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0623\u0648\u0644 \u0641\u0648\u0631\u0627\u064b\u060c \u0648\u064a\u0643\u062a\u0641\u064a \u0628\u0627\u0633\u062a\u064a\u062f\u0627\u0639 \u0627\u0644\u062b\u0627\u0646\u064a \u0630\u0627\u0643\u0631\u0629\u064e \u0623\u0635\u062d\u0627\u0628\u0647\u060c \u0644\u0627 \u0644\u0623\u0646 \u0627\u0644\u062d\u062f\u064a\u062b \u0643\u0644\u0627\u0645\u064c \u0645\u0646 \u0639\u0646\u062f\u0647 \u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0644\u0646\u0628\u0648\u0629 \u0628\u0647\u060c \u0628\u0644 \u0644\u0623\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0648\u062d\u0649\u064b \u0628\u0647 \u0628\u0646\u0641\u0633 \u0627\u0644\u0644\u0641\u0638 \u0648\u0627\u0644\u062d\u0631\u0648\u0641 \u0628\u0648\u0627\u0633\u0637\u0629 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0623\u0645\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u0641\u0645\u0639\u0646\u0627\u0647 \u0648\u062d\u064a\u064c \u0645\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0648\u0644\u0643\u0646 \u0644\u0641\u0638\u064e\u0647 \u0648\u062a\u0631\u0643\u064a\u0628\u064e\u0647 \u0645\u0646 \u0639\u0646\u062f\u0647 \ufdfa\u060c \u0641\u0643\u0627\u0646 \u064a\u064f\u062d\u0627\u0630\u0650\u0631 \u0623\u0646 \u064a\u062e\u062a\u0644\u0637 \u0643\u0644\u0627\u0645\u064f \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u064a\u062a\u0644\u0642\u0627\u0647 \u0645\u0646 \u062c\u0628\u0631\u064a\u0644 \u0628\u0643\u0644\u0627\u0645\u0647 \u0647\u0648.","\u062b\u0627\u0646\u064a\u0627\u064b: \u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u064a\u064f\u0633\u0623\u0644 \u0639\u0646 \u0628\u0639\u0636 \u0627\u0644\u0623\u0645\u0648\u0631 \u0641\u0644\u0627 \u064a\u064f\u062c\u064a\u0628\u060c \u0648\u0631\u0628\u0645\u0627 \u0645\u0631\u064e\u0651 \u0639\u0644\u0649 \u0633\u0643\u0648\u062a\u0647 \u0632\u0645\u0646\u064c \u0637\u0648\u064a\u0644 \u062d\u062a\u0649 \u062a\u0646\u0632\u0644 \u0622\u064a\u0629 \u0641\u064a \u0634\u0623\u0646 \u0633\u0624\u0627\u0644\u0647\u060c \u0648\u0631\u0628\u0645\u0627 \u062a\u0635\u0631\u064e\u0651\u0641 \u0641\u064a \u0628\u0639\u0636 \u0627\u0644\u0623\u0645\u0648\u0631 \u0639\u0644\u0649 \u0648\u062c\u0647 \u0645\u0639\u064a\u0646 \u0641\u062a\u0646\u0632\u064e\u0651\u0644\u064e\u062a \u0622\u064a\u0627\u062a\u064c \u062a\u0635\u0631\u0641\u0647 \u0639\u0646 \u0630\u0644\u0643 \u0627\u0644\u0648\u062c\u0647\u060c \u0648\u0631\u0628\u0645\u0627 \u0627\u0646\u0637\u0648\u062a \u0639\u0644\u0649 \u0639\u062a\u0628\u064d \u0623\u0648 \u0644\u0648\u0645.","\u062b\u0627\u0644\u062b\u0627\u064b: \u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0645\u064a\u064b\u0651\u0627\u060c \u0648\u0644\u064a\u0633 \u0645\u0646 \u0627\u0644\u0645\u0645\u0643\u0646 \u0623\u0646 \u064a\u0639\u0644\u0645 \u0625\u0646\u0633\u0627\u0646\u064c \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0645\u0643\u0627\u0634\u0641\u0629 \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u062d\u0642\u0627\u0626\u0642 \u062a\u0627\u0631\u064a\u062e\u064a\u0629 \u0643\u0642\u0635\u0629 \u064a\u0648\u0633\u0641 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0623\u0645\u0650\u0651 \u0645\u0648\u0633\u0649 \u062d\u064a\u0646 \u0623\u0644\u0642\u064e\u062a \u0648\u0644\u064a\u062f\u064e\u0647\u0627 \u0641\u064a \u0627\u0644\u064a\u0645\u0651\u060c \u0648\u0642\u0635\u0629 \u0641\u0631\u0639\u0648\u0646\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0647\u0630\u0627 \u0645\u0646 \u062c\u0645\u0644\u0629 \u0627\u0644\u062d\u0650\u0643\u064e\u0645 \u0641\u064a \u0643\u0648\u0646\u0647 \ufdfa \u0623\u0645\u064a\u064b\u0651\u0627 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u062a\u0644\u064f\u0648 \u0645\u0650\u0646 \u0642\u064e\u0628\u0644\u0650\u0647\u0650 \u0645\u0650\u0646 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064f\u0637\u0651\u064f\u0647\u064f \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u0625\u0650\u0630\u064b\u0627 \u0644\u0651\u064e\u0627\u0631\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0645\u064f\u0628\u0637\u0650\u0644\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0639\u0646\u0643\u0628\u0648\u062a","\u0631\u0627\u0628\u0639\u0627\u064b: \u0625\u0646 \u0635\u0650\u062f\u0642\u064e \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \ufdfa \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0646\u0629\u064b \u0645\u0639 \u0642\u0648\u0645\u0647 \u0648\u0627\u0634\u062a\u0647\u0627\u0631\u0647 \u0641\u064a\u0647\u0645 \u0628\u0630\u0644\u0643\u060c \u064a\u0633\u062a\u062f\u0639\u064a \u0623\u0646 \u064a\u0643\u0648\u0646 \ufdfa \u0635\u0627\u062f\u0642\u0627\u064b \u0645\u0639 \u0646\u0641\u0633\u0647 \u0645\u0646 \u0642\u0628\u0644\u060c \u0648\u0644\u0630\u0627 \u0641\u0644\u0627 \u0628\u062f \u0623\u0646 \u064a\u0643\u0648\u0646 \u0642\u062f \u0642\u0636\u0649 \u0641\u064a \u062f\u0631\u0627\u0633\u062a\u0647 \u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0648\u062d\u064a \u0639\u0644\u0649 \u0623\u064a \u0634\u0643 \u064a\u062e\u0627\u064a\u0644 \u0644\u0639\u064a\u0646\u064a\u0647 \u0623\u0648 \u0641\u0643\u0631\u0647\u060c \u0648\u0643\u0623\u0646 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062c\u0627\u0621\u062a \u0631\u062f\u064e\u0651\u0627\u064b \u0644\u062f\u0631\u0627\u0633\u062a\u0647 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0634\u0623\u0646 \u0646\u0641\u0633\u0647 \u0645\u0639 \u0627\u0644\u0648\u062d\u064a\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0641\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0632\u064e\u0644\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0643\u064e \u0641\u064e\u0627\u0633\u0623\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0627\u0644\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0644\u0650\u0643\u064e \u0644\u064e\u0642\u064e\u062f \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0627\u0644\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0645\u064f\u0645\u062a\u064e\u0631\u0650\u064a\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u064a\u0648\u0646\u0633","\u0648\u0644\u0647\u0630\u0627 \u0631\u064f\u0648\u0650\u064a\u064e \u0623\u0646 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0642\u0627\u0644 \u0628\u0639\u062f \u0646\u0632\u0648\u0644 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629: \xab\u0644\u0627 \u0623\u0634\u0643 \u0648\u0644\u0627 \u0623\u0633\u0623\u0644\xbb."],t.s)
