B.aFX=s(["\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u0642\u0631\u0622\u0646\u064a \u064a\u064f\u062d\u062f\u0650\u0651\u062b\u0647\u0645 \u0639\u0646 \u0642\u0635\u0629 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0645\u0639 \u0622\u062f\u0645\u060c \u0648\u064a\u0634\u0631\u062d \u0644\u0647\u0645 \u062d\u0642\u064a\u0642\u0629 \u0627\u0644\u0635\u0631\u0627\u0639 \u0628\u064a\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0639\u062f\u0648\u0647 \u0627\u0644\u0644\u062f\u0648\u062f \u0627\u0644\u0630\u064a \u062d\u0627\u0648\u0644 \u0625\u063a\u0648\u0627\u0621 \u0623\u0628\u064a\u0647\u0645 \u0622\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0645\u0646 \u0630\u0644\u0643 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u062a\u0650\u0646\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u064e\u0627\u0646\u064f \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062e\u0631\u064e\u062c\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u064a\u064e\u0646\u0632\u0650\u0639\u064f \u0639\u064e\u0646\u0647\u064f\u0645\u064e\u0627 \u0644\u0650\u0628\u064e\u0627\u0633\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u0622\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u064e\u0627\u0643\u064f\u0645 \u0647\u064f\u0648\u064e \u0648\u064e\u0642\u064e\u0628\u0650\u064a\u0644\u064f\u0647\u064f \u0645\u0650\u0646 \u062d\u064e\u064a\u062b\u064f \u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u0646\u064e\u0647\u064f\u0645 \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0646\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0645\u0650\u0646\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0639\u0631\u0627\u0641.","\u0648\u0642\u062f \u0639\u0644\u064e\u0651\u0645\u062a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0631\u0639\u064a\u0644\u064e \u0627\u0644\u0623\u0648\u0644 \u0642\u0636\u0627\u064a\u0627 \u0645\u0647\u0645\u0629 \u0641\u064a \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0635\u0648\u0631 \u0648\u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f \u0648\u0627\u0644\u0623\u062e\u0644\u0627\u0642\u060c \u0645\u0646 \u0623\u0628\u0631\u0632\u0647\u0627: \u0623\u0646 \u0622\u062f\u0645 \u0647\u0648 \u0623\u0635\u0644 \u0627\u0644\u0628\u0634\u0631\u060c \u0648\u0623\u0646 \u062c\u0648\u0647\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0637\u0627\u0639\u0629\u064f \u0627\u0644\u0645\u0637\u0644\u0642\u0629 \u0644\u0644\u0647\u060c \u0645\u0639 \u0625\u0642\u0631\u0627\u0631 \u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0644\u0644\u0648\u0642\u0648\u0639 \u0641\u064a \u0627\u0644\u062e\u0637\u064a\u0626\u0629\u060c \u0648\u0645\u0627 \u0639\u0644\u064e\u0651\u0645\u064e\u062a\u0647 \u062e\u0637\u064a\u0626\u0629\u064f \u0622\u062f\u0645 \u0645\u0646 \u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0631\u0628\u060c \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0648\u0628\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631\u060c \u0648\u0627\u0644\u0627\u062d\u062a\u0631\u0627\u0632 \u0645\u0646 \u0627\u0644\u062d\u0633\u062f \u0648\u0627\u0644\u0643\u0628\u0631\u060c \u0648\u0625\u062f\u0631\u0627\u0643 \u0623\u0646 \u0625\u0628\u0644\u064a\u0633 \u0647\u0648 \u0627\u0644\u0639\u062f\u0648 \u0627\u0644\u0623\u0648\u0644 \u0644\u0622\u062f\u0645 \u0648\u0632\u0648\u062c\u0647 \u0648\u0630\u0631\u064a\u062a\u0647\u0645\u0627\u060c \u0648\u0645\u0646 \u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u064a \u0627\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0627\u0644\u0643\u0631\u0627\u0645 \u0644\u0645\u062d\u0627\u0631\u0628\u0629 \u0647\u0630\u0627 \u0627\u0644\u0639\u062f\u0648 \u0627\u0644\u0645\u0628\u064a\u0646 \u0627\u0644\u062a\u062e\u0627\u0637\u0628\u064f \u0628\u0623\u062d\u0633\u0646 \u0627\u0644\u0643\u0644\u0627\u0645\u060c \u0627\u0645\u062a\u062b\u0627\u0644\u0627\u064b \u0644\u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0633\u064e\u0646\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u064e\u0627\u0646\u064e \u064a\u064e\u0646\u0632\u064e\u063a\u064f \u0628\u064e\u064a\u0646\u064e\u0647\u064f\u0645 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u064e\u0627\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0625\u0650\u0646\u0633\u064e\u0627\u0646\u0650 \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u0633\u0631\u0627\u0621."],t.s)
