B.aFe=s(["\u0643\u0627\u0646\u062a \u0645\u0643\u0629\u064f \u062d\u0631\u0645\u0627\u064b \u0622\u0645\u0646\u0627\u064b\u060c \u0648\u0645\u0631\u0643\u0632\u0627\u064b \u0644\u0644\u062a\u062c\u0627\u0631\u0629\u060c \u062a\u062d\u0637\u064f\u0651 \u0639\u0646\u062f\u064e\u0647 \u0631\u062d\u0627\u0644\u064f \u0627\u0644\u0642\u0648\u0627\u0641\u0644 \u0645\u0646 \u062c\u0645\u064a\u0639 \u0623\u0646\u062d\u0627\u0621 \u0627\u0644\u062c\u0632\u064a\u0631\u0629\u060c \u0648\u062a\u0644\u062a\u0642\u064a \u0641\u064a\u0647 \u0623\u0644\u0633\u0646\u0629\u064f \u0627\u0644\u0639\u0631\u0628\u0650 \u0639\u0644\u0649 \u0627\u062e\u062a\u0644\u0627\u0641\u0650 \u0642\u0628\u0627\u0626\u0644\u0650\u0647\u0627 \u0648\u0644\u0647\u062c\u0627\u062a\u0650\u0647\u0627\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646 \u0646\u0651\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0627\u0644\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0643\u064e \u0646\u064f\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641 \u0645\u0650\u0646 \u0623\u064e\u0631\u0636\u0650\u0646\u064e\u0627 \u0623\u064e\u0648\u064e\u0644\u064e\u0645 \u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646 \u0644\u0651\u064e\u0647\u064f\u0645 \u062d\u064e\u0631\u064e\u0645\u064b\u0627 \u0622\u0645\u0650\u0646\u064b\u0627 \u064a\u064f\u062c\u0628\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0647\u0650 \u062b\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0621\u064d \u0631\u0651\u0650\u0632\u0642\u064b\u0627 \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u062b\u064e\u0631\u064e\u0647\u064f\u0645 \u0644\u064e\u0627 \u064a\u064e\u0639\u0644\u064e\u0645\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0642\u0635\u0635","\u0648\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u0643\u0627\u0646\u0629\u0650 \u0643\u0627\u0646\u062a \u0642\u0631\u064a\u0634\u064c \u062a\u0633\u062a\u0645\u062f\u064f\u0651 \u0627\u0644\u0633\u064a\u0627\u062f\u0629\u064e \u0639\u0644\u0649 \u062c\u0632\u064a\u0631\u0629\u0650 \u0627\u0644\u0639\u0631\u0628\u060c \u0641\u0644\u0645\u0627 \u0628\u064f\u0639\u0650\u062b\u064e \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \ufdfa\u060c \u0623\u062f\u0631\u0643\u062a \u0642\u0631\u064a\u0634\u064c \u0645\u0646\u0630 \u0627\u0644\u0644\u062d\u0638\u0629\u0650 \u0627\u0644\u0623\u0648\u0644\u0649 \u0623\u0646\u064e\u0651 \u062f\u0639\u0648\u0629\u064e \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \u0645\u062d\u0645\u062f\u064d \ufdfa \u062e\u0637\u0631\u064c \u064a\u064f\u0647\u062f\u0650\u0651\u062f\u064f \u0633\u064a\u0627\u062f\u062a\u064e\u0647\u0627 \u0648\u0645\u0643\u0627\u0646\u062a\u064e\u0647\u0627 \u0628\u064a\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644\u060c \u0641\u0642\u0631\u064e\u0651\u0631\u062a \u0645\u062d\u0627\u0631\u0628\u0629\u064e \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0627\u062a\u062e\u0630\u062a \u0643\u0644\u064e\u0651 \u0627\u0644\u0648\u0633\u0627\u0626\u0644\u0650 \u0644\u0625\u064a\u0642\u0627\u0641\u0650\u0647\u0627 \u0648\u0625\u0633\u0643\u0627\u062a\u0650 \u0635\u0648\u062a\u0650\u0647\u0627.","\u0625\u0646\u064e\u0651 \u0622\u0644\u0629\u064e \u0627\u0644\u0642\u0645\u0639\u0650 \u0627\u0644\u062a\u064a \u0627\u062a\u064e\u0651\u062e\u0630\u062a\u0647\u0627 \u0642\u0631\u064a\u0634\u064c \u0644\u0644\u062a\u0646\u0643\u064a\u0644\u0650 \u0628\u0627\u0644\u062f\u0639\u0648\u0629\u060c \u062a\u0644\u0628\u064e\u0651\u0633\u064e\u062a \u0628\u0623\u062b\u0648\u0627\u0628\u064d \u0634\u062a\u0651\u0649\u060c \u0641\u0645\u0646\u0647\u0627 \u062a\u0643\u0630\u064a\u0628\u064c \u064a\u064f\u062c\u062d\u064e\u062f\u064f \u0628\u0647 \u0627\u0644\u062d\u0642\u064f\u0651 \u0648\u064a\u064f\u0635\u064e\u062f\u064f\u0651 \u0628\u0647 \u0627\u0644\u0646\u0627\u0633\u064f \u0639\u0646 \u0633\u0645\u0627\u0639\u0650\u0647\u060c \u0648\u0645\u0646\u0647\u0627 \u0633\u062e\u0631\u064a\u0629\u064c \u0648\u0627\u0633\u062a\u0647\u0632\u0627\u0621\u064c \u064a\u064f\u0631\u0627\u062f\u064f \u0628\u0647\u0645\u0627 \u0643\u0633\u0631\u064f \u0627\u0644\u0639\u0632\u064a\u0645\u0629\u0650 \u0648\u0627\u0644\u0646\u064e\u0651\u064a\u0644\u064f \u0645\u0646 \u0642\u062f\u0631\u0650 \u0627\u0644\u062f\u0639\u0648\u0629\u0650 \u0648\u0635\u0627\u062d\u0628\u0650\u0647\u0627\u060c \u0648\u0645\u0646\u0647\u0627 \u062a\u0647\u062f\u064a\u062f\u064c \u0648\u0648\u0639\u064a\u062f\u064c \u062a\u064f\u0634\u0647\u064e\u0631\u064f \u0628\u0647 \u0623\u0644\u0633\u0646\u0629\u064f \u0627\u0644\u0637\u063a\u0627\u0629\u060c \u0648\u0645\u0646\u0647\u0627 \u0625\u063a\u0631\u0627\u0621\u064c \u064a\u064f\u0628\u062a\u064e\u063a\u0649 \u0628\u0647 \u0627\u0644\u0641\u062a\u0646\u0629\u064f \u0639\u0646 \u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0645\u0646\u0647\u0627 \u0625\u064a\u0630\u0627\u0621\u064c \u064a\u0645\u062a\u062f\u064f\u0651 \u0645\u0646 \u062c\u0631\u062d\u0650 \u0627\u0644\u0644\u0633\u0627\u0646\u0650 \u0625\u0644\u0649 \u062c\u0631\u062d\u0650 \u0627\u0644\u062c\u0633\u062f\u060c \u0648\u0645\u0646\u0647\u0627 \u062d\u0635\u0627\u0631\u064c \u064a\u064f\u0636\u064a\u064e\u0651\u0642\u064f \u0628\u0647 \u0627\u0644\u062e\u0646\u0627\u0642\u064f \u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0645\u0646\u0647\u0627 \u0628\u0637\u0634\u064c \u064a\u064f\u0631\u0627\u062f\u064f \u0628\u0647 \u0625\u0630\u0644\u0627\u0644\u064f \u0627\u0644\u062c\u0633\u062f\u0650 \u0644\u0639\u0644\u064e\u0651 \u0627\u0644\u0631\u0648\u062d\u064e \u062a\u0646\u0643\u0633\u0631\u060c \u063a\u064a\u0631\u064e \u0623\u0646\u064e\u0651 \u0642\u0644\u0648\u0628\u0627\u064b \u0622\u0645\u0646\u064e\u062a \u0628\u0631\u0628\u0650\u0651\u0647\u0627\u060c \u0644\u0645 \u062a\u0643\u0646 \u0644\u062a\u064f\u0633\u0627\u0648\u0650\u0645\u064e \u0639\u0644\u0649 \u0639\u0642\u064a\u062f\u062a\u0650\u0647\u0627\u060c \u0648\u0644\u0627 \u062a\u0631\u0636\u0649 \u0628\u0627\u0644\u062f\u0646\u064a\u0629\u0650 \u0641\u064a \u062f\u064a\u0646\u0647\u0627\u060c \u0641\u0635\u0645\u062f\u064e\u062a \u0623\u0645\u0627\u0645 \u0630\u0644\u0643 \u0627\u0644\u0637\u0627\u063a\u0648\u062a\u060c \u0644\u062a\u0643\u062a\u0628\u064e \u0641\u0635\u0644\u0627\u064b \u0641\u064a \u0645\u0631\u062d\u0644\u0629\u0650 \u0627\u0644\u0635\u0628\u0631\u0650 \u0648\u0627\u0644\u0635\u0645\u0648\u062f."],t.s)
