B.aK2=s([" \u0627\u062c\u062a\u064e\u0645\u0639\u062a \u0642\u0631\u064a\u0634 \u064a\u0648\u0645\u064b\u0627\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0627\u0646\u0638\u0631\u0648\u0627 \u0623\u0639\u0644\u0645\u064e\u0643\u0645 \u0628\u0627\u0644\u0633\u062d\u0631 \u0648\u0627\u0644\u0643\u0647\u0627\u0646\u0629 \u0648\u0627\u0644\u0634\u0639\u0631\u060c \u0641\u0644\u064a\u0623\u062a\u0650 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0630\u064a \u0641\u0631\u064e\u0651\u0642 \u062c\u0645\u0627\u0639\u062a\u0646\u0627\u060c \u0648\u0634\u062a\u064e\u0651\u062a \u0623\u0645\u0631\u0646\u0627\u060c \u0648\u0639\u0627\u0628 \u062f\u064a\u0646\u0646\u0627\u060c \u0641\u0644\u064a\u0643\u0644\u0650\u0651\u0645\u0647\u060c \u0648\u0644\u064a\u0646\u0638\u0631 \u0645\u0627\u0630\u0627 \u064a\u0631\u062f\u064f\u0651 \u0639\u0644\u064a\u0647\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0645\u0627 \u0646\u0639\u0644\u0645 \u0623\u062d\u062f\u064b\u0627 \u063a\u064a\u0631 \u0639\u062a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0623\u0646\u062a \u064a\u0627 \u0623\u0628\u0627 \u0627\u0644\u0648\u0644\u064a\u062f\u060c \u0641\u0623\u062a\u0627\u0647 \u0639\u062a\u0628\u0629 \u0641\u0642\u0627\u0644: \u064a\u0627 \u0645\u062d\u0645\u062f\u060c \u0623\u0646\u062a \u062e\u064a\u0631\u064c \u0623\u0645 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628\u061f \u0641\u0633\u0643\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0642\u0627\u0644: \u0641\u0625\u0646 \u0643\u0646\u062a \u062a\u0632\u0639\u0645 \u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u062e\u064a\u0631\u064c \u0645\u0646\u0643 \u0641\u0642\u062f \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0622\u0644\u0647\u0629 \u0627\u0644\u062a\u064a \u0639\u0650\u0628\u062a\u060c \u0648\u0625\u0646 \u0643\u0646\u062a \u062a\u0632\u0639\u0645 \u0623\u0646\u0643 \u062e\u064a\u0631\u064c \u0645\u0646\u0647\u0645 \u0641\u062a\u0643\u0644\u064e\u0651\u0645 \u062d\u062a\u0649 \u0646\u0633\u0645\u0639 \u0642\u0648\u0644\u0643\u060c \u0625\u0646\u0627 \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0631\u0623\u064a\u0646\u0627 \u0633\u064e\u062e\u0644\u0629\u064b \u0642\u0637 \u0623\u0634\u0623\u0645\u064e \u0639\u0644\u0649 \u0642\u0648\u0645\u0643 \u0645\u0646\u0643\u060c \u0641\u0631\u064e\u0651\u0642\u062a \u062c\u0645\u0627\u0639\u062a\u0646\u0627\u060c \u0648\u0634\u062a\u064e\u0651\u062a \u0623\u0645\u0631\u0646\u0627\u060c \u0648\u0639\u0650\u0628\u062a \u062f\u064a\u0646\u0646\u0627\u060c \u0648\u0641\u0636\u062d\u062a\u0646\u0627 \u0641\u064a \u0627\u0644\u0639\u0631\u0628 \u062d\u062a\u0649 \u0644\u0642\u062f \u0637\u0627\u0631 \u0641\u064a\u0647\u0645 \u0623\u0646 \u0641\u064a \u0642\u0631\u064a\u0634 \u0633\u0627\u062d\u0631\u064b\u0627\u060c \u0648\u0623\u0646 \u0641\u064a \u0642\u0631\u064a\u0634 \u0643\u0627\u0647\u0646\u064b\u0627\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0646\u0646\u062a\u0638\u0631 \u0625\u0644\u0627 \u0645\u062b\u0644 \u0635\u064a\u062d\u0629 \u0627\u0644\u062d\u064f\u0628\u0644\u0649 \u0623\u0646 \u064a\u0642\u0648\u0645 \u0628\u0639\u0636\u0646\u0627 \u0625\u0644\u0649 \u0628\u0639\u0636 \u0628\u0627\u0644\u0633\u064a\u0648\u0641 \u062d\u062a\u0649 \u0646\u062a\u0641\u0627\u0646\u0649.","\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0644\u060c \u0625\u0646 \u0643\u0627\u0646 \u0625\u0646\u0645\u0627 \u0628\u0643 \u0627\u0644\u062d\u0627\u062c\u0629\u064f \u062c\u0645\u0639\u0646\u0627 \u0644\u0643 \u0645\u0646 \u0623\u0645\u0648\u0627\u0644\u0646\u0627 \u062d\u062a\u0649 \u062a\u0643\u0648\u0646 \u0623\u063a\u0646\u0649 \u0642\u0631\u064a\u0634\u064d \u0631\u062c\u0644\u064b\u0627\u060c \u0648\u0625\u0646 \u0643\u0627\u0646 \u0625\u0646\u0645\u0627 \u0628\u0643 \u0627\u0644\u0628\u0627\u0647\u064f \u0641\u0627\u062e\u062a\u0631 \u0623\u064a\u064e\u0651 \u0646\u0633\u0627\u0621 \u0642\u0631\u064a\u0634 \u0634\u0626\u062a\u064e \u0641\u0644\u0646\u0632\u0648\u0650\u0651\u062c\u0643 \u0639\u0634\u0631\u064b\u0627\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0623\u064e\u0641\u064e\u0631\u064e\u063a\u062a\u064e\u061f\xbb \u0642\u0627\u0644: \u0646\u0639\u0645\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \ufd3f\u062d\u0645 \u06dd \u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064c \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0645\u064e\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u06dd \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a \u0622\u064a\u064e\u0627\u062a\u064f\u0647\u064f \u0642\u064f\u0631\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0644\u0651\u0650\u0642\u064e\u0648\u0645\u064d \u064a\u064e\u0639\u0644\u064e\u0645\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0641\u0635\u0644\u062a\u060c \u0625\u0644\u0649 \u0623\u0646 \u0628\u0644\u063a: \ufd3f\u0641\u064e\u0625\u0650\u0646 \u0623\u064e\u0639\u0631\u064e\u0636\u064f\u0648\u0627 \u0641\u064e\u0642\u064f\u0644 \u0623\u064e\u0646\u0630\u064e\u0631\u062a\u064f\u0643\u064f\u0645 \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064b \u0645\u0651\u0650\u062b\u0644\u064e \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u0650 \u0639\u064e\u0627\u062f\u064d \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0641\u0635\u0644\u062a\u060c \u0641\u0642\u0627\u0644 \u0639\u062a\u0628\u0629: \u062d\u0633\u0628\u064f\u0643 \u062d\u0633\u0628\u064f\u0643\u060c \u0645\u0627 \u0639\u0646\u062f\u0643 \u063a\u064a\u0631 \u0647\u0630\u0627\u061f \u0642\u0627\u0644: \xab\u0644\u0627\xbb\u060c \u0641\u0631\u062c\u064e\u0639\u064e \u0625\u0644\u0649 \u0642\u0631\u064a\u0634\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0645\u0627 \u0648\u0631\u0627\u0621\u064e\u0643\u061f \u0641\u0642\u0627\u0644: \u0645\u0627 \u062a\u0631\u064e\u0643\u062a\u064f \u0634\u064a\u0626\u064b\u0627 \u0623\u0631\u0649 \u0623\u0646\u0643\u0645 \u062a\u064f\u0643\u0644\u0645\u0648\u0646\u0647 \u0628\u0647 \u0625\u0644\u0627 \u0643\u0644\u0645\u062a\u064f\u0647\u060c \u0642\u0627\u0644\u0648\u0627: \u0647\u0644 \u0623\u062c\u0627\u0628\u0643\u061f \u0642\u0627\u0644: \u0646\u0639\u064e\u0645\u060c \u0642\u0627\u0644 \u0648\u0627\u0644\u0630\u064a \u0646\u0635\u064e\u0628\u0647\u0627 \u0628\u064e\u0646\u064a\u0629\u064b\u060c \u0645\u0627 \u0641\u0647\u0650\u0645\u062a\u064f \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u0642\u0627\u0644\u060c \u063a\u064a\u0631\u064e \u0623\u0646\u0651\u064e\u0647 \u0642\u0627\u0644: \ufd3f\u0623\u064e\u0646\u0630\u064e\u0631\u062a\u064f\u0643\u064f\u0645 \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064b \u0645\u0651\u0650\u062b\u0644\u064e \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u0650 \u0639\u064e\u0627\u062f\u064d \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0641\u0635\u0644\u062a\u060c \u0642\u0627\u0644\u0648\u0627: \u0648\u064e\u064a\u0644\u0643\u064e \u064a\u064f\u0643\u0644\u0645\u0643\u064e \u0631\u062c\u064f\u0644 \u0628\u0627\u0644\u0639\u0631\u0628\u064a\u0629\u0650\u060c \u0641\u0644\u0627 \u062a\u062f\u0631\u064a \u0645\u0627 \u0642\u0627\u0644\u061f \u0642\u0627\u0644: \u0644\u0627 \u0648\u0627\u0644\u0644\u0647\u0650\u060c \u0645\u0627 \u0641\u0647\u0650\u0645\u062a\u064f \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u0642\u0627\u0644 \u063a\u064a\u0631\u064e \u0630\u0650\u0643\u0631\u0650 \u0627\u0644\u0635\u0627\u0639\u0642\u0629\u0650."],t.s)
