B.aEk=s(["\u0642\u0627\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u0628\u0633\u0629 \u0627\u0644\u0633\u0644\u0645\u064a: \u0643\u0646\u062a\u064f \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0623\u0638\u0646\u064f\u0651 \u0623\u0646 \u0627\u0644\u0646\u0627\u0633\u064e \u0639\u0644\u0649 \u0636\u0644\u0627\u0644\u0629\u060c \u0648\u0623\u0646\u0647\u0645 \u0644\u064a\u0633\u0648\u0627 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0648\u0647\u0645 \u064a\u0639\u0628\u062f\u0648\u0646 \u0627\u0644\u0623\u0648\u062b\u0627\u0646\u060c \u0641\u0633\u0645\u0639\u062a\u064f \u0628\u0631\u062c\u0644 \u0628\u0645\u0643\u0629 \u064a\u064f\u062e\u0628\u0631 \u0623\u062e\u0628\u0627\u0631\u0627\u064b\u060c \u0641\u0642\u0639\u062f\u062a\u064f \u0639\u0644\u0649 \u0631\u0627\u062d\u0644\u062a\u064a \u0641\u0642\u062f\u0650\u0645\u062a\u064f \u0639\u0644\u064a\u0647\u060c \u0641\u0625\u0630\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u064f\u0633\u062a\u062e\u0641\u064a\u0627\u064b\u060c \u062c\u064f\u0631\u0622\u0621 \u0639\u0644\u064a\u0647 \u0642\u0648\u0645\u064f\u0647\u060c \u0641\u062a\u0644\u0637\u064e\u0651\u0641\u062a\u064f \u062d\u062a\u0649 \u062f\u062e\u0644\u062a\u064f \u0639\u0644\u064a\u0647 \u0628\u0645\u0643\u0629\u060c \u0641\u0642\u0644\u062a\u064f \u0644\u0647: \u0645\u0627 \u0623\u0646\u062a\u061f \u0642\u0627\u0644: \xab\u0623\u0646\u0627 \u0646\u0628\u064a\xbb\u060c \u0641\u0642\u0644\u062a\u064f: \u0648\u0645\u0627 \u0646\u0628\u064a\u061f \u0642\u0627\u0644: \xab\u0623\u0631\u0633\u0644\u0646\u064a \u0627\u0644\u0644\u0647\xbb\u060c \u0641\u0642\u0644\u062a\u064f: \u0648\u0628\u0623\u064a \u0634\u064a\u0621 \u0623\u0631\u0633\u0644\u0643\u061f \u0642\u0627\u0644: \xab\u0623\u0631\u0633\u0644\u0646\u064a \u0628\u0635\u0644\u0629 \u0627\u0644\u0623\u0631\u062d\u0627\u0645\u060c \u0648\u0643\u0633\u0631 \u0627\u0644\u0623\u0648\u062b\u0627\u0646\u060c \u0648\u0623\u0646 \u064a\u064f\u0648\u062d\u064e\u0651\u062f \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u064f\u0634\u0631\u0643 \u0628\u0647 \u0634\u064a\u0621\xbb\u060c \u0642\u0644\u062a\u064f \u0644\u0647: \u0641\u0645\u0646 \u0645\u0639\u0643 \u0639\u0644\u0649 \u0647\u0630\u0627\u061f \u0642\u0627\u0644: \xab\u062d\u064f\u0631\u064c\u0651 \u0648\u0639\u0628\u062f\xbb\u060c \u0648\u0643\u0627\u0646 \u0645\u0639\u0647 \u064a\u0648\u0645\u0626\u0630\u064d \u0623\u0628\u0648 \u0628\u0643\u0631 \u0648\u0628\u0644\u0627\u0644 \u0645\u0645\u0646 \u0622\u0645\u0646 \u0628\u0647\u060c \u0641\u0642\u0644\u062a\u064f: \u0625\u0646\u064a \u0645\u062a\u064e\u0651\u0628\u0639\u064f\u0643\u060c \u0641\u0642\u0627\u0644: \xab\u0625\u0646\u0643 \u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0630\u0644\u0643 \u064a\u0648\u0645\u064e\u0643 \u0647\u0630\u0627\u060c \u0623\u0644\u0627 \u062a\u0631\u0649 \u062d\u0627\u0644\u064a \u0648\u062d\u0627\u0644 \u0627\u0644\u0646\u0627\u0633\u061f \u0648\u0644\u0643\u0646 \u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0623\u0647\u0644\u0643\u060c \u0641\u0625\u0630\u0627 \u0633\u0645\u0639\u062a\u064e \u0628\u064a \u0642\u062f \u0638\u0647\u0631\u062a\u064f \u0641\u0623\u062a\u0650\u0646\u064a\xbb.","\u0641\u0630\u0647\u0628\u062a\u064f \u0625\u0644\u0649 \u0623\u0647\u0644\u064a\u060c \u0648\u0642\u062f\u0650\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0643\u0646\u062a\u064f \u0641\u064a \u0623\u0647\u0644\u064a \u0623\u062a\u062e\u064a\u064e\u0651\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0648\u0623\u0633\u0623\u0644 \u0627\u0644\u0646\u0627\u0633\u060c \u062d\u062a\u0649 \u0642\u062f\u0650\u0645 \u0639\u0644\u064a\u064e\u0651 \u0646\u0641\u0631\u064c \u0645\u0646 \u0623\u0647\u0644 \u064a\u062b\u0631\u0628\u060c \u0641\u0642\u0644\u062a\u064f: \u0645\u0627 \u0641\u0639\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0630\u064a \u0642\u062f\u0650\u0645 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u061f \u0641\u0642\u0627\u0644\u0648\u0627: \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u064a\u0647 \u0633\u0650\u0631\u0627\u0639\u060c \u0648\u0642\u062f \u0623\u0631\u0627\u062f \u0642\u0648\u0645\u064f\u0647 \u0642\u062a\u0644\u064e\u0647 \u0641\u0644\u0645 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0627 \u0630\u0644\u0643\u060c \u0641\u0642\u062f\u0650\u0645\u062a\u064f \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0641\u062f\u062e\u0644\u062a\u064f \u0639\u0644\u064a\u0647\u060c \u0641\u0642\u0644\u062a\u064f: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0623\u062a\u0639\u0631\u0641\u0646\u064a\u061f \u0642\u0627\u0644: \xab\u0646\u0639\u0645\u060c \u0623\u0646\u062a \u0627\u0644\u0630\u064a \u0644\u0642\u064a\u062a\u064e\u0646\u064a \u0628\u0645\u0643\u0629\xbb."],t.s)
