B.aIt=s(["\u0645\u0646 \u0627\u0644\u0633\u0646\u0646 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0639\u0627\u0645\u0644 \u0645\u0639\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0633\u0646\u0629\u064f \u0627\u0644\u0623\u062e\u0630 \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0648\u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u062c\u0645\u0639 \u0633\u0628\u0628\u060c \u0648\u0647\u0648 \u0643\u0644 \u0634\u064a\u0621 \u064a\u064f\u062a\u0648\u0635\u064e\u0651\u0644 \u0628\u0647 \u0625\u0644\u0649 \u063a\u064a\u0631\u0647\u060c \u0648\u0647\u0630\u0647 \u0627\u0644\u0633\u0646\u0629 \u0645\u064f\u0642\u0631\u0631\u064e\u0651\u0629 \u0641\u064a \u0643\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0635\u0648\u0631\u0629 \u0648\u0627\u0636\u062d\u0629\u060c \u0641\u0644\u0642\u062f \u062e\u0644\u0642 \u0627\u0644\u0644\u0647 \u0647\u0630\u0627 \u0627\u0644\u0643\u0648\u0646 \u0628\u0642\u062f\u0631\u062a\u0647\u060c \u0648\u0623\u0648\u062f\u0639\u0647 \u0645\u0646 \u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0648\u0627\u0644\u0633\u0646\u0646 \u0645\u0627 \u064a\u0636\u0645\u0646 \u0627\u0633\u062a\u0642\u0631\u0627\u0631\u0647 \u0648\u0627\u0633\u062a\u0645\u0631\u0627\u0631\u0647\u060c \u0648\u062c\u0639\u0644 \u0627\u0644\u0645\u0633\u0628\u0628\u0627\u062a\u0650 \u0645\u0631\u062a\u0628\u0637\u0629\u064b \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0628\u0639\u062f \u0625\u0631\u0627\u062f\u062a\u0647 \u062a\u0639\u0627\u0644\u0649.","\u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0644\u062c\u0639\u0644 \u0643\u0644 \u0647\u0630\u0647 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 -\u0628\u0642\u062f\u0631\u062a\u0647 \u0627\u0644\u0645\u0637\u0644\u0642\u0629- \u063a\u064a\u0631 \u0645\u062d\u062a\u0627\u062c\u0629 \u0625\u0644\u0649 \u0633\u0628\u0628\u060c \u0648\u0644\u0643\u0646 \u0647\u0643\u0630\u0627 \u0627\u0642\u062a\u0636\u062a \u0645\u0634\u064a\u0626\u062a\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u0643\u0645\u062a\u0647\u060c \u0625\u0630 \u064a\u0631\u064a\u062f \u0623\u0646 \u064a\u0648\u062c\u0651\u0647 \u062e\u0644\u0642\u0647 \u0625\u0644\u0649 \u0636\u0631\u0648\u0631\u0629 \u0645\u0631\u0627\u0639\u0627\u0629 \u0647\u0630\u0647 \u0627\u0644\u0633\u0646\u0629 \u0644\u064a\u0633\u062a\u0642\u064a\u0645 \u0633\u064a\u0631 \u0627\u0644\u062d\u064a\u0627\u0629 \u0639\u0644\u0649 \u0627\u0644\u0646\u062d\u0648 \u0627\u0644\u0630\u064a \u064a\u0631\u064a\u062f\u0647 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0648\u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0646\u0629 \u0627\u0644\u0623\u062e\u0630 \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0628\u0627\u0631\u0632\u0629\u064b \u0641\u064a \u0643\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0635\u0648\u0631\u0629 \u0648\u0627\u0636\u062d\u0629\u060c \u0641\u0625\u0646\u0647\u0627 \u0643\u0630\u0644\u0643 \u0645\u0642\u0631\u0631\u0629 \u0641\u064a \u0643\u062a\u0627\u0628\u0647 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0648\u0644\u0642\u062f \u0648\u062c\u0651\u0647 \u0627\u0644\u0644\u0647 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0625\u0644\u0649 \u0648\u062c\u0648\u0628 \u0645\u0631\u0627\u0639\u0627\u062a\u0647\u0627 \u0641\u064a \u0643\u0644 \u0634\u0624\u0648\u0646\u0647\u0645 \u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629 \u0648\u0627\u0644\u0623\u062e\u0631\u0648\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0648\u0627\u0621\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0642\u064f\u0644\u0650 \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0633\u064e\u064a\u064e\u0631\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064e\u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0648\u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0630\u064e\u0644\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u0627\u0645\u0652\u0634\u064f\u0648\u0627 \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0643\u0650\u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646 \u0631\u0651\u0650\u0632\u0652\u0642\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u0644\u0643\u060c \u0648\u0644\u0642\u062f \u0623\u062e\u0628\u0631\u0646\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0633\u064a\u062f\u0629 \u0645\u0631\u064a\u0645 \u0623\u0646 \u062a\u064f\u0628\u0627\u0634\u0631 \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0648\u0647\u064a \u0641\u064a \u0623\u0634\u062f\u0651 \u062d\u0627\u0644\u0627\u062a \u0636\u0639\u0641\u0647\u0627\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0647\u064f\u0632\u0651\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u0650 \u0628\u0650\u062c\u0650\u0630\u0652\u0639\u0650 \u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u064e\u0629\u0650 \u062a\u064f\u0633\u064e\u0627\u0642\u0650\u0637\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u0650 \u0631\u064f\u0637\u064e\u0628\u064b\u0627 \u062c\u064e\u0646\u0650\u064a\u0651\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0645\u0631\u064a\u0645\u060c \u0648\u0647\u0643\u0630\u0627 \u064a\u0624\u0643\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u0636\u0631\u0648\u0631\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0641\u064a \u0643\u0644 \u0627\u0644\u0623\u0645\u0648\u0631 \u0648\u0627\u0644\u0623\u062d\u0648\u0627\u0644.","\u0648\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0643\u0627\u0646 \u0623\u0648\u0639\u0649 \u0627\u0644\u0646\u0627\u0633 \u0628\u0647\u0630\u0647 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u0629\u060c \u0641\u0643\u0627\u0646 -\u0648\u0647\u0648 \u064a\u0624\u0633\u0633 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u062f\u0648\u0644\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629- \u064a\u0623\u062e\u0630 \u0628\u0643\u0644 \u0645\u0627 \u0641\u064a \u0648\u0633\u0639\u0647 \u0645\u0646 \u0623\u0633\u0628\u0627\u0628\u060c \u0648\u0644\u0627 \u064a\u062a\u0631\u0643 \u0634\u064a\u0626\u064b\u0627 \u064a\u0633\u064a\u0631\u064b\u0627 \u062c\u064f\u0632\u0627\u0641\u064b\u0627\u060c \u0648\u0643\u0627\u0646 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u064a\u0648\u062c\u0651\u0647 \u0623\u0635\u062d\u0627\u0628\u0647 \u062f\u0627\u0626\u0645\u064b\u0627 \u0625\u0644\u0649 \u0645\u0631\u0627\u0639\u0627\u0629 \u0647\u0630\u0647 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u0629 \u0641\u064a \u0623\u0645\u0648\u0631\u0647\u0645 \u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629 \u0648\u0627\u0644\u0623\u062e\u0631\u0648\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0648\u0627\u0621."],t.s)
