B.aGk=s(["\u0642\u0627\u0644 \u062c\u0627\u0628\u0631 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a: \u0645\u0643\u062b \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0645\u0643\u0629 \u0639\u0634\u0631 \u0633\u0646\u064a\u0646 \u064a\u062a\u064e\u0651\u0628\u0639\u064f \u0627\u0644\u0646\u0627\u0633\u064e \u0641\u064a \u0645\u0646\u0627\u0632\u0644\u0647\u0645 \u0628\u0639\u064f\u0643\u0627\u0638 \u0648\u0645\u064e\u062c\u0650\u0646\u064e\u0651\u0629 \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0633\u0645 \u0628\u0645\u0646\u0649 \u064a\u0642\u0648\u0644: \xab\u0645\u0646 \u064a\u064f\u0624\u0648\u064a\u0646\u064a\u061f \u0645\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u0646\u064a \u062d\u062a\u0649 \u0623\u064f\u0628\u0644\u0650\u0651\u063a \u0631\u0633\u0627\u0644\u0629\u064e \u0631\u0628\u064a \u0648\u0644\u0647 \u0627\u0644\u062c\u0646\u0629\u061f\xbb\u060c \u062d\u062a\u0649 \u0625\u0646 \u0627\u0644\u0631\u062c\u0644\u064e \u0644\u064a\u062e\u0631\u062c\u064f \u0645\u0646 \u0627\u0644\u064a\u0645\u0646 \u0623\u0648 \u0645\u064f\u0636\u064e\u0631\u060c \u0641\u064a\u0623\u062a\u064a\u0647 \u0642\u0648\u0645\u064f\u0647 \u0641\u064a\u0642\u0648\u0644\u0648\u0646: \u0627\u062d\u0630\u064e\u0631 \u063a\u0644\u0627\u0645\u064e \u0642\u0631\u064a\u0634 \u0644\u0627 \u064a\u064e\u0641\u062a\u0650\u0646\u064e\u0651\u0643\u060c \u0648\u064a\u0645\u0634\u064a \u0628\u064a\u0646 \u0631\u062c\u0627\u0644\u0647\u0645 \u0648\u0647\u0645 \u064a\u064f\u0634\u064a\u0631\u0648\u0646 \u0625\u0644\u064a\u0647 \u0628\u0627\u0644\u0623\u0635\u0627\u0628\u0639\u060c \u062d\u062a\u0649 \u0628\u0639\u062b\u0646\u0627 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0647 \u0645\u0646 \u064a\u062b\u0631\u0628 \u0641\u0622\u0648\u064a\u0646\u0627\u0647\u060c \u0648\u0635\u062f\u064e\u0651\u0642\u0646\u0627\u0647\u060c \u0641\u064a\u062e\u0631\u062c\u064f \u0627\u0644\u0631\u062c\u0644\u064f \u0645\u0646\u0627 \u0641\u064a\u0624\u0645\u0646\u064f \u0628\u0647 \u0648\u064a\u064e\u0642\u0631\u064e\u0623\u064f \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0641\u064a\u0646\u0642\u0644\u0628\u064f \u0625\u0644\u0649 \u0623\u0647\u0644\u0647 \u0641\u064a\u064f\u0633\u0644\u0645\u0648\u0646 \u0628\u0625\u0633\u0644\u0627\u0645\u0647\u060c \u062d\u062a\u0649 \u0644\u0627 \u064a\u0628\u0642\u0649 \u062f\u0627\u0631\u064c \u0645\u0646 \u062f\u0648\u0631 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0625\u0644\u0627 \u0648\u0641\u064a\u0647\u0627 \u0631\u0647\u0637\u064c \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u064a\u064f\u0638\u0647\u0650\u0631\u0648\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","\u0627\u0644\u0645\u0639\u0627\u0646\u064a: [\u0639\u064f\u0643\u0627\u0638: \u0633\u0648\u0642 \u0645\u0646 \u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u0639\u0631\u0628 \u0627\u0644\u0645\u0634\u0647\u0648\u0631\u0629 \u0642\u0631\u0628 \u0645\u0643\u0629\u060c \u064a\u062c\u062a\u0645\u0639 \u0641\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0644\u0644\u062a\u062c\u0627\u0631\u0629 \u0648\u0627\u0644\u0634\u0639\u0631 | \u0645\u064e\u062c\u0650\u0646\u064e\u0651\u0629: \u0633\u0648\u0642 \u0645\u0646 \u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u0639\u0631\u0628 \u0642\u0631\u0628 \u0645\u0643\u0629\u060c \u0645\u0646 \u0645\u0648\u0627\u0633\u0645 \u0627\u0644\u062d\u062c \u0648\u0627\u0644\u062a\u062c\u0627\u0631\u0629 | \u0631\u064e\u0647\u0637\u064c: \u062c\u0645\u0627\u0639\u0629\u064c \u0645\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0645\u0627 \u0628\u064a\u0646 \u062b\u0644\u0627\u062b\u0629\u064d \u0648\u0639\u0634\u0631\u0629]."],t.s)
