B.aUv=s(["\u064a\u0638\u0647\u0631 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0639\u0638\u064a\u0645 \u0641\u064a \u0628\u064a\u0639\u0629 \u0627\u0644\u0639\u0642\u0628\u0629\u060c \u0625\u0630 \u062a\u0645\u062a \u0641\u064a \u0638\u0631\u0648\u0641 \u063a\u0627\u064a\u0629 \u0641\u064a \u0627\u0644\u0635\u0639\u0648\u0628\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u062a\u0645\u062b\u0644 \u062a\u062d\u062f\u064a\u064b\u0627 \u062e\u0637\u064a\u0631\u064b\u0627 \u0648\u062c\u0631\u064a\u0626\u064b\u0627 \u0644\u0642\u0648\u0649 \u0627\u0644\u0634\u0631\u0643 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0648\u0642\u062a\u060c \u0648\u0644\u0630\u0644\u0643 \u0643\u0627\u0646 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0646\u0628\u0648\u064a \u0644\u0646\u062c\u0627\u062d\u0647\u0627 \u0641\u064a \u063a\u0627\u064a\u0629 \u0627\u0644\u0625\u062d\u0643\u0627\u0645 \u0648\u0627\u0644\u062f\u0642\u0629\u060c \u0648\u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0646\u062d\u0648 \u0627\u0644\u062a\u0627\u0644\u064a:","\u0627\u0644\u0623\u0648\u0644: \u0633\u0650\u0631\u0650\u0651\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0645\u0628\u0627\u064a\u0639\u064a\u0646 \u062d\u062a\u0649 \u0644\u0627 \u064a\u0646\u0643\u0634\u0641 \u0627\u0644\u0623\u0645\u0631\u060c \u0641\u0642\u062f \u0643\u0627\u0646 \u0648\u0641\u062f \u0627\u0644\u0645\u0628\u0627\u064a\u0639\u0629 \u0627\u0644\u0645\u0633\u0644\u0645 \u0633\u0628\u0639\u064a\u0646 \u0631\u062c\u0644\u0627\u064b \u0648\u0627\u0645\u0631\u0623\u062a\u064a\u0646 \u0645\u0646 \u0628\u064a\u0646 \u0648\u0641\u062f \u064a\u062b\u0631\u0628\u064a \u0642\u0650\u0648\u0627\u0645\u064f\u0647 \u0646\u062d\u0648 \u062e\u0645\u0633\u0645\u0627\u0626\u0629\u060c \u0645\u0645\u0627 \u064a\u062c\u0639\u0644 \u062d\u0631\u0643\u0629 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0633\u0628\u0639\u064a\u0646 \u0635\u0639\u0628\u0629 \u0648\u0627\u0646\u062a\u0642\u0627\u0644\u0647\u0645 \u0623\u0645\u0631\u064b\u0627 \u063a\u064a\u0631 \u0645\u064a\u0633\u0648\u0631\u060c \u0648\u0642\u062f \u062a\u062d\u062f\u062f \u0645\u0648\u0639\u062f \u0627\u0644\u0644\u0642\u0627\u0621 \u0641\u064a \u062b\u0627\u0646\u064a \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u0634\u0631\u064a\u0642 \u0628\u0639\u062f \u062b\u0644\u062b \u0627\u0644\u0644\u064a\u0644\u060c \u062d\u064a\u062b \u0627\u0644\u0646\u0648\u0645 \u0642\u062f \u0636\u0631\u0628 \u0623\u0639\u064a\u0646 \u0627\u0644\u0642\u0648\u0645 \u0648\u0647\u062f\u0623\u062a \u0627\u0644\u0631\u0650\u0651\u062c\u0644\u060c \u0643\u0645\u0627 \u062a\u0645 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0643\u0627\u0646 \u0641\u064a \u0627\u0644\u0634\u0639\u0628 \u0627\u0644\u0623\u064a\u0645\u0646 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0639\u064a\u0646 \u0645\u0646 \u0642\u062f \u064a\u0633\u062a\u064a\u0642\u0638 \u0645\u0646 \u0627\u0644\u0646\u0648\u0645 \u0644\u062d\u0627\u062c\u0629.","\u0627\u0644\u062b\u0627\u0646\u064a: \u0627\u0644\u062e\u0631\u0648\u062c \u0627\u0644\u0645\u0646\u0638\u0645 \u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0645\u0628\u0627\u064a\u0639\u064a\u0646 \u0625\u0644\u0649 \u0645\u0648\u0639\u062f \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639 \u0648\u0645\u0643\u0627\u0646\u0647\u060c \u0641\u062e\u0631\u062c\u0648\u0627 \u064a\u062a\u0633\u0644\u0644\u0648\u0646 \u0645\u0633\u062a\u062e\u0641\u064a\u0646 \u0631\u062c\u0644\u064b\u0627 \u0631\u062c\u0644\u064b\u0627 \u0623\u0648 \u0631\u062c\u0644\u064a\u0646 \u0631\u062c\u0644\u064a\u0646.","\u0627\u0644\u062b\u0627\u0644\u062b: \u0636\u064e\u0631\u0628 \u0627\u0644\u0633\u0650\u0651\u0631\u064a\u0629 \u0627\u0644\u062a\u0627\u0645\u0629 \u0639\u0644\u0649 \u0645\u0648\u0639\u062f \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639 \u0648\u0645\u0643\u0627\u0646\u0647\u060c \u0628\u062d\u064a\u062b \u0644\u0645 \u064a\u0639\u0644\u0645 \u0628\u0647 \u0633\u0648\u0649 \u0627\u0644\u0639\u0628\u0627\u0633 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0627\u0644\u0630\u064a \u062c\u0627\u0621 \u0645\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u064a\u062a\u0648\u062b\u0642 \u0644\u0647\u060c \u0648\u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0639\u064a\u0646\u064b\u0627 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0641\u0645 \u0627\u0644\u0634\u0650\u0651\u0639\u0628\u060c \u0648\u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0639\u0644\u0649 \u0641\u0645 \u0627\u0644\u0637\u0631\u064a\u0642 \u0639\u064a\u0646\u064b\u0627 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0643\u0630\u0644\u0643\u060c \u0623\u0645\u0627 \u0645\u0646 \u0639\u062f\u0627\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u063a\u064a\u0631\u0647\u0645 \u0641\u0644\u0645 \u064a\u0643\u0646 \u064a\u0639\u0644\u0645 \u0639\u0646 \u0627\u0644\u0623\u0645\u0631 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0642\u062f \u0623\u0645\u0631 \u062c\u0645\u0627\u0639\u0629\u064e \u0627\u0644\u0645\u0628\u0627\u064a\u0639\u064a\u0646 \u0623\u0646 \u0644\u0627 \u064a\u0631\u0641\u0639\u0648\u0627 \u0627\u0644\u0635\u0648\u062a \u0648\u0623\u0646 \u0644\u0627 \u064a\u0637\u064a\u0644\u0648\u0627 \u0641\u064a \u0627\u0644\u0643\u0644\u0627\u0645\u060c \u062d\u0630\u0631\u064b\u0627 \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u064a\u0646 \u064a\u0633\u0645\u0639 \u0635\u0648\u062a\u0647\u0645 \u0623\u0648 \u064a\u064e\u062c\u064f\u0633\u064e\u0651 \u062d\u0631\u0643\u062a\u0647\u0645.","\u0627\u0644\u0631\u0627\u0628\u0639: \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0625\u062e\u0641\u0627\u0621 \u0648\u0627\u0644\u0633\u0631\u064a\u0629 \u062d\u064a\u0646 \u0643\u0634\u0641 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0623\u0645\u0631 \u0627\u0644\u0628\u064a\u0639\u0629\u060c \u0641\u0623\u0645\u0631\u0647\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u064a\u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0631\u062d\u0627\u0644\u0647\u0645 \u0648\u0644\u0627 \u064a\u064f\u062d\u062f\u0650\u062b\u0648\u0627 \u0634\u064a\u0626\u064b\u0627\u060c \u0631\u0627\u0641\u0636\u064b\u0627 \u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644 \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u0644\u062d\u0629 \u0627\u0644\u062a\u064a \u0644\u0645 \u062a\u062a\u0647\u064a\u0623 \u0644\u0647\u0627 \u0627\u0644\u0638\u0631\u0648\u0641 \u0628\u0639\u062f\u060c \u0648\u0639\u0646\u062f\u0645\u0627 \u062c\u0627\u0621\u062a \u0642\u0631\u064a\u0634 \u062a\u0633\u062a\u0628\u0631\u0626 \u0627\u0644\u062e\u0628\u0631 \u0645\u064e\u0648\u064e\u0651\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0633\u0643\u0648\u062a \u0623\u0648 \u0628\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0628\u0627\u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0630\u064a \u064a\u0634\u063a\u0644 \u0639\u0646 \u0627\u0644\u0645\u0648\u0636\u0648\u0639.","\u0627\u0644\u062e\u0627\u0645\u0633: \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u0623\u062e\u064a\u0631\u0629 \u0645\u0646 \u0644\u064a\u0627\u0644\u064a \u0627\u0644\u062d\u062c \u0648\u0647\u064a \u0644\u064a\u0644\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u0639\u0634\u0631 \u0645\u0646 \u0630\u064a \u0627\u0644\u062d\u062c\u0629\u060c \u062d\u064a\u062b \u0633\u064a\u0646\u0641\u0631 \u0627\u0644\u062d\u062c\u0627\u062c \u0625\u0644\u0649 \u0628\u0644\u0627\u062f\u0647\u0645 \u0638\u0647\u0631 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062a\u0627\u0644\u064a\u060c \u0648\u0645\u0646 \u062b\u064e\u0645\u064e\u0651 \u062a\u0636\u064a\u0642 \u0627\u0644\u0641\u0631\u0635\u0629 \u0623\u0645\u0627\u0645 \u0642\u0631\u064a\u0634 \u0641\u064a \u0627\u0639\u062a\u0631\u0627\u0636\u0647\u0645 \u0623\u0648 \u062a\u0639\u0648\u064a\u0642\u0647\u0645 \u0625\u0630\u0627 \u0627\u0646\u0643\u0634\u0641 \u0623\u0645\u0631 \u0627\u0644\u0628\u064a\u0639\u0629\u060c \u0648\u0647\u0648 \u0623\u0645\u0631 \u0645\u062a\u0648\u0642\u0639 \u0648\u0647\u0630\u0627 \u0645\u0627 \u062d\u062f\u062b."],t.s)
