B.aTv=s(["\u064a\u064e\u0638\u0647\u0631 \u0627\u0644\u062d\u0628 \u0627\u0644\u0639\u0645\u064a\u0642 \u0627\u0644\u0630\u064a \u0633\u064e\u064a\u0637\u0631 \u0639\u0644\u0649 \u0642\u0644\u0628 \u0623\u0628\u064a \u0628\u0643\u0631 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0643\u0645\u0627 \u064a\u064e\u0638\u0647\u0631 \u062d\u064f\u0628 \u0633\u0627\u0626\u0631 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0623\u062c\u0645\u0639\u064a\u0646 \u0641\u064a \u0633\u064a\u0631\u0629 \u0627\u0644\u062d\u0628\u064a\u0628 \u0627\u0644\u0645\u0635\u0637\u0641\u0649 \ufdfa\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u062d\u0628 \u0627\u0644\u0631\u0628\u0627\u0646\u064a \u0643\u0627\u0646 \u0646\u0627\u0628\u0639\u0627\u064b \u0645\u0646 \u0627\u0644\u0642\u0644\u0628 \u0648\u0628\u0625\u062e\u0644\u0627\u0635\u060c \u0644\u0645 \u064a\u0643\u0646 \u062d\u064f\u0628\u064e\u0651 \u0646\u0641\u0627\u0642\u060c \u0648\u0644\u0627 \u0646\u0627\u0628\u0639\u0627\u064b \u0645\u0646 \u0645\u0635\u0644\u062d\u0629 \u062f\u0646\u064a\u0648\u064a\u0629\u060c \u0648\u0644\u0627 \u0631\u063a\u0628\u0629\u064b \u0641\u064a \u0645\u0646\u0641\u0639\u0629\u060c \u0648\u0644\u0627 \u0631\u0647\u0628\u0629\u064b \u0645\u0646 \u0645\u0643\u0631\u0648\u0647 \u0642\u062f \u064a\u0642\u0639\u060c \u0648\u0645\u0646 \u0623\u0633\u0628\u0627\u0628 \u0647\u0630\u0627 \u0627\u0644\u062d\u0628 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0635\u0641\u0627\u062a\u064f\u0647 \u0627\u0644\u0642\u064a\u0627\u062f\u064a\u0629 \u0627\u0644\u0631\u0634\u064a\u062f\u0629\u060c \u0641\u0647\u0648 \u064a\u064e\u0633\u0647\u0631 \u0644\u064a\u0646\u0627\u0645\u0648\u0627\u060c \u0648\u064a\u062a\u0639\u0628 \u0644\u064a\u0633\u062a\u0631\u064a\u062d\u0648\u0627\u060c \u0648\u064a\u062c\u0648\u0639 \u0644\u064a\u064f\u0634\u0628\u0650\u0639\u0648\u0627\u060c \u0643\u0627\u0646 \u064a\u064e\u0641\u0631\u062d \u0644\u0641\u0631\u062d\u0647\u0645 \u0648\u064a\u064e\u062d\u0632\u0646 \u0644\u062d\u0632\u0646\u0647\u0645\u060c \u0641\u0645\u0646 \u0633\u064e\u0644\u064e\u0643 \u0633\u064f\u0646\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0645\u0639 \u0635\u062d\u0627\u0628\u062a\u0647 \u0641\u064a \u062d\u064a\u0627\u062a\u0647 \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0627\u0644\u0639\u0627\u0645\u0629\u060c \u0648\u0634\u0627\u0631\u0643 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0623\u0641\u0631\u0627\u062d\u0647\u0645 \u0648\u0623\u062a\u0631\u0627\u062d\u0647\u0645\u060c \u0648\u0643\u0627\u0646 \u0639\u0645\u0644\u0647 \u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0647\u060c \u0623\u0635\u0627\u0628\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u062d\u0628 \u0625\u0646 \u0643\u0627\u0646 \u0645\u0646 \u0627\u0644\u0632\u0639\u0645\u0627\u0621 \u0623\u0648 \u0627\u0644\u0642\u0627\u062f\u0629 \u0623\u0648 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0646 \u0641\u064a \u0623\u0645\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","\u0625\u0646 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0647\u064a \u0627\u0644\u062a\u064a \u062a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u062a\u0642\u0648\u062f \u0627\u0644\u0623\u0631\u0648\u0627\u062d \u0642\u0628\u0644 \u0643\u0644 \u0634\u064a\u0621\u060c \u0648\u062a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u062a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u0646\u0641\u0648\u0633 \u0642\u0628\u0644 \u063a\u064a\u0631\u0647\u0627\u060c \u0648\u0639\u0644\u0649 \u0642\u062f\u0631 \u0625\u062d\u0633\u0627\u0646 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u064a\u0643\u0648\u0646 \u0625\u062d\u0633\u0627\u0646 \u0627\u0644\u062c\u0646\u0648\u062f\u060c \u0648\u0639\u0644\u0649 \u0642\u062f\u0631 \u0627\u0644\u0628\u0630\u0644 \u0645\u0646 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u064a\u0643\u0648\u0646 \u0627\u0644\u062d\u0628 \u0645\u0646 \u0627\u0644\u062c\u0646\u0648\u062f\u060c \u0641\u0642\u062f \u0643\u0627\u0646 \ufdfa \u0631\u062d\u064a\u0645\u0627\u064b \u0648\u0634\u064e\u0641\u0648\u0642\u0627\u064b \u0628\u062c\u0646\u0648\u062f\u0647 \u0648\u0623\u062a\u0628\u0627\u0639\u0647\u060c \u0641\u0647\u0648 \u0644\u0645 \u064a\u064f\u0647\u0627\u062c\u0650\u0631 \u0625\u0644\u0627 \u0628\u0639\u062f \u0623\u0646 \u0647\u0627\u062c\u0631 \u0645\u0639\u0638\u0645 \u0623\u0635\u062d\u0627\u0628\u0647\u060c \u0648\u0644\u0645 \u064a\u064e\u0628\u0642\u064e \u0625\u0644\u0627 \u0627\u0644\u0645\u0633\u062a\u0636\u0639\u0641\u0648\u0646 \u0648\u0627\u0644\u0645\u0641\u062a\u0648\u0646\u0648\u0646 \u0648\u0645\u0646 \u0643\u0627\u0646\u062a \u0644\u0647 \u0645\u0647\u0645\u0627\u062a\u064c \u062e\u0627\u0635\u0629 \u0628\u0627\u0644\u0647\u062c\u0631\u0629."],t.s)
