B.aCy=s(["\u0625\u0646 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0623\u0645\u0631\u064c \u0636\u0631\u0648\u0631\u064a \u0648\u0648\u0627\u062c\u0628\u060c \u0648\u0644\u0643\u0646 \u0644\u0627 \u064a\u0639\u0646\u064a \u0630\u0644\u0643 \u062f\u0627\u0626\u0645\u0627\u064b \u062d\u0635\u0648\u0644\u064e \u0627\u0644\u0646\u062a\u064a\u062c\u0629\u060c \u0630\u0644\u0643 \u0644\u0623\u0646\u064e\u0651 \u0647\u0630\u0627 \u0623\u0645\u0631\u064c \u064a\u062a\u0639\u0644\u0642 \u0628\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0645\u0634\u064a\u0626\u062a\u0647\u060c \u0648\u0645\u0646 \u0647\u0646\u0627 \u0643\u0627\u0646 \u0627\u0644\u062a\u0648\u0643\u0644 \u0623\u0645\u0631\u0627\u064b \u0636\u0631\u0648\u0631\u064a\u0627\u064b\u060c \u0648\u0647\u0648 \u0645\u0646 \u0628\u0627\u0628 \u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0625\u0646 \u0631\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0639\u062f\u064e\u0651 \u0643\u0644\u064e\u0651 \u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0648\u0627\u062a\u062e\u0630 \u0643\u0644\u064e\u0651 \u0627\u0644\u0648\u0633\u0627\u0626\u0644\u060c \u0648\u0644\u0643\u0646\u0647 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647 \u0645\u0639 \u0627\u0644\u0644\u0647\u060c \u064a\u062f\u0639\u0648\u0647 \u0648\u064a\u0633\u062a\u0646\u0635\u0631\u0647 \u0623\u0646 \u064a\u064f\u0643\u064e\u0644\u0650\u0651\u0644\u064e \u0633\u0639\u064a\u064e\u0647 \u0628\u0627\u0644\u0646\u062c\u0627\u062d\u060c \u0648\u0647\u0646\u0627 \u064a\u064f\u0633\u062a\u062c\u0627\u0628 \u0627\u0644\u062f\u0639\u0627\u0621\u060c \u0648\u064a\u064e\u0646\u0635\u0631\u0641 \u0627\u0644\u0642\u0648\u0645 \u0628\u0639\u062f \u0623\u0646 \u0648\u0642\u0641\u0648\u0627 \u0639\u0644\u0649 \u0628\u0627\u0628 \u0627\u0644\u063a\u0627\u0631\u060c \u0648\u062a\u064e\u0633\u064a\u062e\u064f \u0641\u064e\u0631\u064e\u0633\u064f \u0633\u064f\u0631\u0627\u0642\u0629 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u064a\u064f\u0643\u064e\u0644\u064e\u0651\u0644\u064f \u0627\u0644\u0639\u0645\u0644 \u0628\u0627\u0644\u0646\u062c\u0627\u062d."],t.s)
